INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes) VALUES ('grammar-01', 'Articles and Nouns (al- and Nouns)', 'grammar', 1, '{"explanation":"Arabic nouns are either definite or indefinite. The definite article is ال (al-). When attached, it changes based on the first letter of the noun—sun letters cause assimilation, moon letters keep the ل sound.","examples":[{"arabic":"الشَّمْسُ","transliteration":"ash-shamsu","meaning":"the sun","rule":"Sun letter — ال assimilates and the ش takes a shadda"},{"arabic":"الْقَمَرُ","transliteration":"al-qamaru","meaning":"the moon","rule":"Moon letter — ال keeps its ل sound"}],"rules":[{"name":"Sun Letters (حروف شمسية)","description":"When ال attaches to a noun starting with one of these letters, the ل is dropped and the following letter takes a shadda","letters":"ت ث د ذ ر ز س ش ص ض ط ظ ل ن","examples":["الشَّمْسُ","الدِّينُ","النُّورُ"]},{"name":"Moon Letters (حروف قمرية)","description":"When ال attaches to a noun starting with one of these letters, the ل is pronounced","letters":"ا ب ج ح خ ع غ ف ق ك م ه و ي","examples":["الْبَابُ","الْجَبَلُ","الْقَمَرُ"]}]}', '[{"type":"multiple_choice","question":"Which of these is a moon letter?","options":["ت","س","ب","ر"],"correct":2,"explanation":"ب is a moon letter. ت، س، and ر are sun letters."},{"type":"fill_blank","question":"Complete: ال + كِتَاب = ___","correct":"الْكِتَابُ","explanation":"ك is a moon letter, so the ل is pronounced."}]', '[]', 20);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes) VALUES ('grammar-02', 'Verb Conjugation — Past Tense (الماضي)', 'grammar', 1, '{"explanation":"Arabic verbs change based on the subject. The past tense (ماضي) is the simplest form — add suffixes to the root to indicate who performed the action.","conjugation_table":{"root":"كتب","meaning":"to write","forms":{"he":"كَتَبَ","she":"كَتَبَتْ","they_two":"كَتَبَا","they_men":"كَتَبُوا","they_women":"كَتَبْنَ","you_m":"كَتَبْتَ","you_f":"كَتَبْتِ","we":"كَتَبْنَا","I":"كَتَبْتُ"}}}', '[{"type":"match","question":"Match the conjugation of كَتَبَ (he wrote) with the correct subject","pairs":[{"item":"كَتَبُوا","answer":"they (men) wrote"},{"item":"كَتَبْنَ","answer":"they (women) wrote"},{"item":"كَتَبْنَا","answer":"we wrote"}]},{"type":"multiple_choice","question":"Which form of كَتَبَ means “they (men) wrote”?","options":["كَتَبُوا","كَتَبْنَ","كَتَبْنَا","كَتَبْتُ"],"correct":0,"explanation":"The masculine plural past suffix is ـُوا. كَتَبْنَ is “they (women) wrote” and كَتَبْنَا is “we wrote”."},{"type":"multiple_choice","question":"The past-tense suffix ـْنَا indicates which subject?","options":["I","we","they (women)","you (feminine)"],"correct":1,"explanation":"كَتَبْنَا is “we wrote”. Note that ـْنَ alone — كَتَبْنَ — is “they (women) wrote”, so the final alif matters."}]', '["grammar-01"]', 25);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes) VALUES ('grammar-03', 'Sentence Structure — Nominal Sentences (الجملة الاسمية)', 'grammar', 1, '{"explanation":"Arabic sentences begin with either a noun (nominal sentence / جملة اسمية) or a verb (verbal sentence / جملة فعلية). A nominal sentence has two parts: the subject (مبتدأ) and the predicate (خبر).","examples":[{"arabic":"الْكِتَابُ مَفْتُوحٌ","transliteration":"al-kitābu maftūḥun","meaning":"The book is open","structure":"مبتدأ + خبر","quranic":false},{"arabic":"اللَّهُ كَبِيرٌ","transliteration":"allāhu kabīrun","meaning":"God is Great","structure":"مبتدأ + خبر","quranic":false}]}', '[{"type":"multiple_choice","question":"Identify the مبتدأ (subject) in: الْبَابُ مَسْدُودٌ","options":["مَسْدُودٌ","الْبَابُ","the whole sentence"],"correct":1,"explanation":"الْبَابُ is the مبتدأ (subject/noun that begins the sentence).","quranic":false},{"type":"multiple_choice","question":"What are the two parts of a nominal sentence (جملة اسمية)?","options":["فعل and فاعل","مبتدأ and خبر","مضاف and مضاف إليه","صفة and موصوف"],"correct":1,"explanation":"A nominal sentence is مبتدأ (subject) + خبر (predicate). فعل and فاعل belong to a verbal sentence."}]', '["grammar-01"]', 20);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes) VALUES ('grammar-04', 'Verb Conjugation — Present Tense (المضارع)', 'grammar', 2, '{"explanation":"The present tense (مضارع) is formed with a prefix, and often a suffix too. The prefix indicates the subject: أ (I), ن (we), ت (you — and “she” in the third person singular), ي (he). Note that ت never marks “he”, and that ي also carries the third person feminine plural, as in يَكْتُبْنَ.","conjugation_table":{"root":"كتب","meaning":"to write","forms":{"I":"أَكْتُبُ","you_m":"تَكْتُبُ","he":"يَكْتُبُ","she":"تَكْتُبُ","we":"نَكْتُبُ","they_m":"يَكْتُبُونَ","they_w":"يَكْتُبْنَ"}}}', '[{"type":"fill_blank","question":"Complete: يَكْتُبُ → they (men) write = ___","correct":"يَكْتُبُونَ","explanation":"The masculine plural present suffix is ُونَ (-ūna) — waw, then noon with a fatha."},{"type":"multiple_choice","question":"Which present-tense form means “we write”?","options":["نَكْتُبُ","يَكْتُبُ","تَكْتُبُ","أَكْتُبُ"],"correct":0,"explanation":"The نـ prefix marks “we”. يـ is “he”, تـ is “you” or “she”, and أـ is “I”."}]', '["grammar-02"]', 25);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes) VALUES ('grammar-05', 'Case Endings — I''rab Basics (الإعراب)', 'grammar', 2, '{"explanation":"Arabic nouns change their ending based on their grammatical role in the sentence. This is called i''rab (إعراب). The three cases are: nominative (مرفوع) with ـُ, accusative (منصوب) with ـَ, genitive (مجرور) with ـِ.","examples":[{"arabic":"جَاءَ الرَّجُلُ","transliteration":"jā''a ar-rajulu","meaning":"The man came","case":"مرفوع (nominative — subject)","quranic":false},{"arabic":"رَأَيْتُ الرَّجُلَ","transliteration":"ra''aytu ar-rajula","meaning":"I saw the man","case":"منصوب (accusative — object)","quranic":false},{"arabic":"ذَهَبْتُ إِلَى الرَّجُلِ","transliteration":"dhahabtu ilā ar-rajuli","meaning":"I went to the man","case":"مجرور (genitive — after preposition)","quranic":false}]}', '[{"type":"multiple_choice","question":"What case ending does the subject of a sentence take?","options":["ـُ (damma)","ـَ (fatha)","ـِ (kasra)"],"correct":0,"explanation":"The subject (فاعل) takes the nominative case with damma (ـُ)."},{"type":"multiple_choice","question":"In ذَهَبْتُ إِلَى الرَّجُلِ, why does الرَّجُلِ end in a kasra?","options":["It is the subject","It follows a preposition, so it is genitive","It is the object of the verb","Every noun ends in a kasra"],"correct":1,"explanation":"إِلَى is a preposition, and a noun after a preposition is genitive (مجرور) — marked with a kasra.","quranic":false}]', '["grammar-03"]', 30);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes) VALUES ('grammar-06', 'The Idafa Construction (الإضافة)', 'grammar', 2, '{"explanation":"Arabic expresses possession by placing two nouns together rather than using a word for “of”. The first noun (المضاف) takes no article and carries whatever case its role in the sentence requires. The second (المضاف إليه) is always genitive. So رَبِّ ٱلْعَٰلَمِينَ is “Lord of the worlds” — two nouns, no connecting word.","examples":[{"arabic":"رَبِّ ٱلْعَٰلَمِينَ","transliteration":"rabbi l-ʿālamīna","meaning":"Lord of the worlds","rule":"المضاف takes no article; المضاف إليه is genitive"},{"arabic":"يَوْمِ ٱلدِّينِ","transliteration":"yawmi d-dīni","meaning":"the Day of Judgement","rule":"A chained idafa: مَٰلِكِ possesses the day, and the day possesses the judgement. Each noun puts the next in the genitive."}],"rules":[{"name":"The first term (المضاف)","description":"Never carries ال and never carries tanween. Its case is set by its role in the wider sentence."},{"name":"The second term (المضاف إليه)","description":"Always genitive (مجرور), whatever the sentence around it is doing."}]}', '[{"type":"multiple_choice","question":"In رَبِّ ٱلْعَٰلَمِينَ, what case is ٱلْعَٰلَمِينَ?","options":["Nominative","Accusative","Genitive","It varies"],"correct":2,"explanation":"The second term of an idafa is always genitive."},{"type":"multiple_choice","question":"Which is NOT allowed on the first term of an idafa?","options":["A case ending","The article ال","A plural form","A feminine ending"],"correct":1,"explanation":"المضاف never takes ال. That is how you recognise the construction."}]', '["grammar-05"]', 20);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes) VALUES ('grammar-07', 'Attached Pronouns (الضمائر المتصلة)', 'grammar', 2, '{"explanation":"Arabic attaches pronouns directly to the end of nouns, verbs and prepositions rather than writing them separately. On a noun the pronoun means possession; on a verb it is the object; on a preposition it is what the preposition governs. The same ending does all three jobs, so context decides.","examples":[{"arabic":"رَبِّكَ","transliteration":"rabbika","meaning":"your Lord","rule":"Noun + attached possessive كَ — “your”. Occurs 81 times as a word on its own."},{"arabic":"فِيهِ","transliteration":"fīhi","meaning":"in it","rule":"Preposition + attached هِ — what the preposition governs"}],"rules":[{"name":"On a noun — possession","description":"رَبِّكَ is “your Lord”. The كَ is the possessor, written as part of the word."},{"name":"On a verb — object","description":"The same endings attach to a verb as its object, not its subject. In فِيهِ the هِ is what فِي governs."},{"name":"Not to be confused with إِيَّاكَ","description":"إِيَّاكَ is a DETACHED pronoun (ضمير منفصل), a word of its own. And نَعْبُدُ carries no attached pronoun at all — its “we” is the نـ prefix, an implied pronoun (ضمير مستتر). Three different categories."}]}', '[{"type":"multiple_choice","question":"Attached to a noun, what does an attached pronoun express?","options":["The subject","Possession","Tense","Case"],"correct":1,"explanation":"On a noun it marks the possessor."},{"type":"multiple_choice","question":"In رَبِّكَ (“your Lord”), which part is the attached pronoun?","options":["كَ — the ending","رَبِّ — the stem","the whole word","there is no pronoun"],"correct":0,"explanation":"رَبِّكَ is the stem رَبِّ (“Lord”) plus the attached pronoun كَ (“your”). Attached pronouns are always the ending."}]', '["grammar-03"]', 18);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes) VALUES ('grammar-08', 'Derived Verb Forms I–IV (الأوزان)', 'grammar', 3, '{"explanation":"Almost every Arabic word is built from a three-letter root poured into a pattern. The pattern changes the meaning in a regular way: Form I is the plain action, Form II often intensifies or makes it causative, Form III makes it mutual, Form IV makes it causative. Learn the patterns and one root gives you a family of words.","examples":[{"arabic":"أَنزَلَ","transliteration":"anzala","meaning":"he sent down","rule":"Form IV of نزل — causative"},{"arabic":"نَزَّلَ","transliteration":"nazzala","meaning":"he sent down gradually","rule":"Form II of the same root — intensive or repeated"}],"rules":[{"name":"Form I (فَعَلَ)","description":"The bare root. The corpus marks Forms II–XII and leaves this one unmarked, because Form I IS the plain triliteral."},{"name":"Form IV (أَفْعَلَ)","description":"Prefixes أ and makes the action causative: to cause something to happen."}]}', '[{"type":"multiple_choice","question":"أَنزَلَ and نَزَّلَ share a root. What differs?","options":["The tense","The derived form, and so the shade of meaning","The subject","Nothing — they are spelling variants"],"correct":1,"explanation":"أَنزَلَ is Form IV and نَزَّلَ is Form II. Same root نزل, different pattern."},{"type":"multiple_choice","question":"Why does the corpus not label Form I explicitly?","options":["An oversight","Form I is the bare root, so an absent marker means Form I","Form I is rare","It labels it as Form 0"],"correct":1,"explanation":"An unmarked verb is Form I. Reading that as “unknown” would drop the commonest form entirely."}]', '["grammar-04"]', 25);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes) VALUES ('grammar-09', 'Demonstratives (أسماء الإشارة)', 'grammar', 2, '{"explanation":"Arabic demonstratives agree with what they point at in gender and number, and distinguish near from far. When a demonstrative is followed by a noun carrying ال, the two together form a single phrase — “this book” — rather than a sentence.","examples":[{"arabic":"ذَٰلِكَ","transliteration":"dhālika","meaning":"that","rule":"Masculine singular, far"},{"arabic":"هَٰذَا","transliteration":"hādhā","meaning":"this","rule":"Masculine singular, near"}],"rules":[{"name":"Near vs far","description":"هَٰذَا points at what is close; ذَٰلِكَ at what is distant, in space or in the discourse."},{"name":"With a definite noun","description":"ذَٰلِكَ ٱلْكِتَٰبُ (2:2) is “that Book” — a phrase, not a sentence. Drop the ال and ذَٰلِكَ becomes the subject of its own sentence: “that is a book”."}]}', '[{"type":"multiple_choice","question":"Which points at something near?","options":["ذَٰلِكَ","هَٰذَا","أُو۟لَـٰئِكَ","تِلْكَ"],"correct":1,"explanation":"هَٰذَا is the near masculine singular; ذَٰلِكَ is its far counterpart."},{"type":"multiple_choice","question":"Which demonstrative is feminine singular and far?","options":["تِلْكَ","هَٰذِهِ","ذَٰلِكَ","هَٰذَا"],"correct":0,"explanation":"تِلْكَ is the far feminine singular. هَٰذِهِ is its near counterpart, and ذَٰلِكَ is far but masculine."}]', '["grammar-03"]', 15);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes) VALUES ('grammar-10', 'Negation (النفي)', 'grammar', 3, '{"explanation":"Arabic negates with different particles depending on what is negated and when. لَا negates a present-tense verb, or negates a category outright. لَمْ is the usual way to negate the past: it precedes a present-tense verb and puts it in the jussive. مَا also negates the past, before a past-tense verb. لَنْ negates the future and takes the subjunctive. Choosing the wrong particle changes the tense, not just the tone.","examples":[{"arabic":"لَا","transliteration":"lā","meaning":"not, no","rule":"Negates the present, or negates a category absolutely"},{"arabic":"مَا","transliteration":"mā","meaning":"not","rule":"Negates the past tense — also serves as “what” elsewhere"}],"rules":[{"name":"لَا with the present","description":"لَا يَعْلَمُ — “he does not know”. The verb stays indicative."},{"name":"مَا with the past","description":"مَا قَالَ — “he did not say”. The verb keeps its past form."},{"name":"لَمْ with the jussive","description":"لَمْ يَكُنْ — “he was not”. The verb looks present but the meaning is past, and the ending is jussive."}]}', '[{"type":"multiple_choice","question":"Which particle negates a past-tense verb?","options":["لَا","مَا","لَنْ","لَيْسَ"],"correct":1,"explanation":"مَا negates a past-tense verb. لَمْ also negates the past but takes a present-tense verb in the jussive, لَا handles the present, and لَنْ the future."},{"type":"multiple_choice","question":"What does لَنْ do besides negate?","options":["Nothing","Puts the verb in the subjunctive","Makes it past","Adds emphasis only"],"correct":1,"explanation":"لَنْ negates the future and governs the subjunctive."}]', '["grammar-04"]', 20);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes) VALUES ('root-Alh', 'The root اله (ا ل ه)', 'grammar', 1, '{"explanation":"The root اله occurs 2,851 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 7 distinct glossed words, tagged in the corpus as PN, N. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"ٱللَّهِ","transliteration":"","meaning":"(of) Allah","rule":"1:1"},{"arabic":"ٱللَّهُ","transliteration":"","meaning":"Allah","rule":"2:7"},{"arabic":"لِّلَّهِ","transliteration":"","meaning":"(to) Allah","rule":"2:98"},{"arabic":"لِلَّهِ","transliteration":"","meaning":"(be) to Allah","rule":"1:2"},{"arabic":"ٱللَّهَ","transliteration":"","meaning":"Allah","rule":"2:9"},{"arabic":"وَٱللَّهُ","transliteration":"","meaning":"And Allah","rule":"2:19"}],"rules":[{"name":"Words on اله","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["ٱللَّهِ","ٱللَّهُ","لِّلَّهِ","لِلَّهِ","ٱللَّهَ","وَٱللَّهُ","بِٱللَّهِ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root اله?","options":["ٱللَّهِ","كَمِشْكَوٰةٍۢ","أَشْكُوا۟","شَيْـًۭٔا"],"correct":0,"explanation":"ٱللَّهِ — glossed \"(of) Allah\" at 1:1 — carries the root اله. The others come from different roots."},{"type":"multiple_choice","question":"What does ٱللَّهُ mean?","options":["and your forefathers","associated partners (with Him)","Allah","and a reward"],"correct":2,"explanation":"\"Allah\", from the word-by-word gloss at 2:7."},{"type":"fill_blank","question":"Type the root of لِّلَّهِ in Arabic (three letters).","correct":"اله","explanation":"اله. Diacritics are ignored when checking, so ا ل ه is enough."}]', '[]', 15);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes) VALUES ('root-qwl', 'The root قول (ق و ل)', 'grammar', 1, '{"explanation":"The root قول occurs 1,722 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 20 distinct glossed words, tagged in the corpus as V, N, in verb form V. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"يَقُولَآ","transliteration":"","meaning":"they [both] say","rule":"2:102"},{"arabic":"قَوْلًا","transliteration":"","meaning":"(the) word","rule":"2:59"},{"arabic":"فَقَالَ","transliteration":"","meaning":"then He said","rule":"2:31"},{"arabic":"وَقُولُوا۟","transliteration":"","meaning":"And say","rule":"2:58"},{"arabic":"قُلْ","transliteration":"","meaning":"Say","rule":"2:80"},{"arabic":"يَقُولُونَ","transliteration":"","meaning":"they say","rule":"2:79"}],"rules":[{"name":"Words on قول","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["يَقُولَآ","قَوْلًا","فَقَالَ","وَقُولُوا۟","قُلْ","يَقُولُونَ","وَقَالُوا۟","يَقُولُ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root قول?","options":["يَقُولَآ","أَثِيمٍ","يَأْتُوا۟","وَيَذْكُرُوا۟"],"correct":0,"explanation":"يَقُولَآ — glossed \"they [both] say\" at 2:102 — carries the root قول. The others come from different roots."},{"type":"multiple_choice","question":"What does قَوْلًا mean?","options":["You give us","you are ordered","(the) word","and (some)thing"],"correct":2,"explanation":"\"(the) word\", from the word-by-word gloss at 2:59."},{"type":"fill_blank","question":"Type the root of فَقَالَ in Arabic (three letters).","correct":"قول","explanation":"قول. Diacritics are ignored when checking, so ق و ل is enough."}]', '["root-Alh"]', 15);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes) VALUES ('root-kwn', 'The root كون (ك و ن)', 'grammar', 1, '{"explanation":"The root كون occurs 1,390 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 25 distinct glossed words, tagged in the corpus as V, N, LOC. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"تَكُونُوٓا۟","transliteration":"","meaning":"be","rule":"2:41"},{"arabic":"كَانَتْ","transliteration":"","meaning":"is","rule":"2:94"},{"arabic":"كُنتُم","transliteration":"","meaning":"you were","rule":"2:91"},{"arabic":"أَكُونَ","transliteration":"","meaning":"I be","rule":"2:67"},{"arabic":"كَانَ","transliteration":"","meaning":"(there) has been","rule":"2:75"},{"arabic":"كَانَا","transliteration":"","meaning":"they [both] were","rule":"2:36"}],"rules":[{"name":"Words on كون","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["تَكُونُوٓا۟","كَانَتْ","كُنتُم","أَكُونَ","كَانَ","كَانَا","تَكُونَ","لَكُنتُم"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root كون?","options":["ٱلْأَرْضِ","إِحْدَى","أَتَىٰكُمْ","تَكُونُوٓا۟"],"correct":3,"explanation":"تَكُونُوٓا۟ — glossed \"be\" at 2:41 — carries the root كون. The others come from different roots."},{"type":"multiple_choice","question":"What does كَانَتْ mean?","options":["is","whom We had given","taking it away","female"],"correct":0,"explanation":"\"is\", from the word-by-word gloss at 2:94."},{"type":"fill_blank","question":"Type the root of كُنتُم in Arabic (three letters).","correct":"كون","explanation":"كون. Diacritics are ignored when checking, so ك و ن is enough."}]', '["root-qwl"]', 15);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes) VALUES ('root-rbb', 'The root ربب (ر ب ب)', 'grammar', 1, '{"explanation":"The root ربب occurs 980 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 23 distinct glossed words, tagged in the corpus as N. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"رَبُّنَا","transliteration":"","meaning":"(is) our Lord","rule":"2:139"},{"arabic":"وَرَبُّكُمْ","transliteration":"","meaning":"and your Lord","rule":"2:139"},{"arabic":"رَبَّكَ","transliteration":"","meaning":"(to) your Lord","rule":"2:61"},{"arabic":"رَّبِّهِمْ","transliteration":"","meaning":"their Lord","rule":"2:5"},{"arabic":"رَبِّهِۦ","transliteration":"","meaning":"his Lord","rule":"2:112"},{"arabic":"رَّبِّكَ","transliteration":"","meaning":"your Lord","rule":"2:147"}],"rules":[{"name":"Words on ربب","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["رَبُّنَا","وَرَبُّكُمْ","رَبَّكَ","رَّبِّهِمْ","رَبِّهِۦ","رَّبِّكَ","رَبَّنَا","رَبُّهُۥ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root ربب?","options":["رَبُّنَا","وَلَيَأْتِيَنَّهُم","ٱللَّهُ","أَشْهَدُ"],"correct":0,"explanation":"رَبُّنَا — glossed \"(is) our Lord\" at 2:139 — carries the root ربب. The others come from different roots."},{"type":"multiple_choice","question":"What does وَرَبُّكُمْ mean?","options":["and your Lord","we will","(of) a poet","his kind"],"correct":0,"explanation":"\"and your Lord\", from the word-by-word gloss at 2:139."},{"type":"fill_blank","question":"Type the root of رَبَّكَ in Arabic (three letters).","correct":"ربب","explanation":"ربب. Diacritics are ignored when checking, so ر ب ب is enough."}]', '["root-kwn"]', 15);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes) VALUES ('root-Amn', 'The root امن (ا م ن)', 'grammar', 1, '{"explanation":"The root امن occurs 879 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 28 distinct glossed words, tagged in the corpus as V, N, ADJ, in verb forms IV, VIII. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"نُؤْمِنُ","transliteration":"","meaning":"We believe","rule":"2:91"},{"arabic":"إِيمَـٰنُكُمْ","transliteration":"","meaning":"your faith","rule":"2:93"},{"arabic":"إِيمَـٰنِكُمْ","transliteration":"","meaning":"your (having) faith","rule":"2:109"},{"arabic":"وَءَامِنُوا۟","transliteration":"","meaning":"And believe","rule":"2:41"},{"arabic":"ءَامِنًۭا","transliteration":"","meaning":"secure","rule":"2:126"},{"arabic":"مُّؤْمِنَةٌ","transliteration":"","meaning":"(who is) believing","rule":"2:221"}],"rules":[{"name":"Words on امن","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["نُؤْمِنُ","إِيمَـٰنُكُمْ","إِيمَـٰنِكُمْ","وَءَامِنُوا۟","ءَامِنًۭا","مُّؤْمِنَةٌ","بِمُؤْمِنِينَ","ءَامَنُوا۟"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root امن?","options":["مُّشْفِقُونَ","يَأْتِيكُم","نُؤْمِنُ","شَىْءٍ"],"correct":2,"explanation":"نُؤْمِنُ — glossed \"We believe\" at 2:91 — carries the root امن. The others come from different roots."},{"type":"multiple_choice","question":"What does إِيمَـٰنُكُمْ mean?","options":["taking","We will give him","gives him","your faith"],"correct":3,"explanation":"\"your faith\", from the word-by-word gloss at 2:93."},{"type":"fill_blank","question":"Type the root of إِيمَـٰنِكُمْ in Arabic (three letters).","correct":"امن","explanation":"امن. Diacritics are ignored when checking, so ا م ن is enough."}]', '["root-rbb"]', 15);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes) VALUES ('root-Elm', 'The root علم (ع ل م)', 'grammar', 1, '{"explanation":"The root علم occurs 854 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 31 distinct glossed words, tagged in the corpus as N, V, ADJ, in verb forms II, V. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"عَلِيمٌۢ","transliteration":"","meaning":"(is) All-Knower","rule":"2:95"},{"arabic":"ٱلْعِلْمِ","transliteration":"","meaning":"the knowledge","rule":"2:120"},{"arabic":"ٱلْعَـٰلَمِينَ","transliteration":"","meaning":"of the universe","rule":"1:2"},{"arabic":"أَعْلَمُ","transliteration":"","meaning":"[I] know","rule":"2:30"},{"arabic":"وَيُعَلِّمُهُمُ","transliteration":"","meaning":"and will teach them","rule":"2:129"},{"arabic":"وَيَتَعَلَّمُونَ","transliteration":"","meaning":"And they learn","rule":"2:102"}],"rules":[{"name":"Words on علم","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["عَلِيمٌۢ","ٱلْعِلْمِ","ٱلْعَـٰلَمِينَ","أَعْلَمُ","وَيُعَلِّمُهُمُ","وَيَتَعَلَّمُونَ","ٱلْعَلِيمُ","فَيَعْلَمُونَ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root علم?","options":["تَذْكِرَةٌۭ","بِـَٔايَـٰتِ","ٱلْـَٔايَـٰتُ","عَلِيمٌۢ"],"correct":3,"explanation":"عَلِيمٌۢ — glossed \"(is) All-Knower\" at 2:95 — carries the root علم. The others come from different roots."},{"type":"multiple_choice","question":"What does ٱلْعِلْمِ mean?","options":["and their families","(of) Allah","they tasted","the knowledge"],"correct":3,"explanation":"\"the knowledge\", from the word-by-word gloss at 2:120."},{"type":"fill_blank","question":"Type the root of ٱلْعَـٰلَمِينَ in Arabic (three letters).","correct":"علم","explanation":"علم. Diacritics are ignored when checking, so ع ل م is enough."}]', '["root-Amn"]', 15);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes) VALUES ('root-qwm', 'The root قوم (ق و م)', 'grammar', 1, '{"explanation":"The root قوم occurs 660 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 35 distinct glossed words, tagged in the corpus as ADJ, V, N, in verb forms X, IV, II. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"لِقَوْمِهِۦ","transliteration":"","meaning":"to his people","rule":"2:54"},{"arabic":"قِيَـٰمًۭا","transliteration":"","meaning":"standing","rule":"3:191"},{"arabic":"يُقِيمَا","transliteration":"","meaning":"they both (can) keep","rule":"2:229"},{"arabic":"ٱلْقَوْمَ","transliteration":"","meaning":"the people","rule":"2:258"},{"arabic":"قَآئِمٌۭ","transliteration":"","meaning":"(was) standing","rule":"3:39"},{"arabic":"وَأَقْوَمُ","transliteration":"","meaning":"and more upright","rule":"2:282"}],"rules":[{"name":"Words on قوم","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["لِقَوْمِهِۦ","قِيَـٰمًۭا","يُقِيمَا","ٱلْقَوْمَ","قَآئِمٌۭ","وَأَقْوَمُ","يَـٰقَوْمِ","ٱلْقَيُّومُ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root قوم?","options":["لِقَوْمِهِۦ","وَءَابَآؤُكُم","يَذُوقُونَ","ءَأَشْفَقْتُمْ"],"correct":0,"explanation":"لِقَوْمِهِۦ — glossed \"to his people\" at 2:54 — carries the root قوم. The others come from different roots."},{"type":"multiple_choice","question":"What does قِيَـٰمًۭا mean?","options":["Your sign","a (distant) term","[the] males","standing"],"correct":3,"explanation":"\"standing\", from the word-by-word gloss at 3:191."},{"type":"fill_blank","question":"Type the root of يُقِيمَا in Arabic (three letters).","correct":"قوم","explanation":"قوم. Diacritics are ignored when checking, so ق و م is enough."}]', '["root-Elm"]', 15);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes) VALUES ('root-Aty', 'The root اتي (ا ت ي)', 'grammar', 1, '{"explanation":"The root اتي occurs 549 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 42 distinct glossed words, tagged in the corpus as V, N, in verb form IV. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"يُؤْتِيهِ","transliteration":"","meaning":"He gives it","rule":"3:73"},{"arabic":"وَءَاتَىٰهُ","transliteration":"","meaning":"and gave him","rule":"2:251"},{"arabic":"وَتُؤْتُوهَا","transliteration":"","meaning":"and give it","rule":"2:271"},{"arabic":"تَأْتِينَآ","transliteration":"","meaning":"comes to us","rule":"2:118"},{"arabic":"ءَاتَيْنَـٰكُم","transliteration":"","meaning":"We have given you","rule":"2:63"},{"arabic":"يُؤْتَ","transliteration":"","meaning":"he has been given","rule":"2:247"}],"rules":[{"name":"Words on اتي","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["يُؤْتِيهِ","وَءَاتَىٰهُ","وَتُؤْتُوهَا","تَأْتِينَآ","ءَاتَيْنَـٰكُم","يُؤْتَ","يَأْتِيَكُمُ","يَأْتِينَكَ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root اتي?","options":["يُؤْتِيهِ","ٱلشَّـٰكِرِينَ","شَأْنٍۢ","تُشْرِكَ"],"correct":0,"explanation":"يُؤْتِيهِ — glossed \"He gives it\" at 3:73 — carries the root اتي. The others come from different roots."},{"type":"multiple_choice","question":"What does وَءَاتَىٰهُ mean?","options":["an ear","others","and gave him","(in) gratitude"],"correct":2,"explanation":"\"and gave him\", from the word-by-word gloss at 2:251."},{"type":"fill_blank","question":"Type the root of وَتُؤْتُوهَا in Arabic (three letters).","correct":"اتي","explanation":"اتي. Diacritics are ignored when checking, so ا ت ي is enough."}]', '["root-qwm"]', 15);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes) VALUES ('root-kfr', 'The root كفر (ك ف ر)', 'grammar', 1, '{"explanation":"The root كفر occurs 525 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 28 distinct glossed words, tagged in the corpus as V, N, ADJ, in verb forms II, IV. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"ٱلْكُفْرَ","transliteration":"","meaning":"[the] disbelief","rule":"2:108"},{"arabic":"كَفَّارٍ","transliteration":"","meaning":"ungrateful","rule":"2:276"},{"arabic":"كُفَّارًا","transliteration":"","meaning":"(to) disbelievers","rule":"2:109"},{"arabic":"لِلْكَـٰفِرِينَ","transliteration":"","meaning":"for the disbelievers","rule":"2:24"},{"arabic":"كَفَرُوا۟","transliteration":"","meaning":"disbelieve[d]","rule":"2:6"},{"arabic":"بِكُفْرِهِمْ","transliteration":"","meaning":"for their disbelief","rule":"2:88"}],"rules":[{"name":"Words on كفر","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["ٱلْكُفْرَ","كَفَّارٍ","كُفَّارًا","لِلْكَـٰفِرِينَ","كَفَرُوا۟","بِكُفْرِهِمْ","وَلِلْكَـٰفِرِينَ","وَكُفْرٌۢ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root كفر?","options":["بِأَمْرِهِۦ","ٱلْكُفْرَ","ٱلْـَٔاخِرَةُ","ءَايَـٰتٍۭ"],"correct":1,"explanation":"ٱلْكُفْرَ — glossed \"[the] disbelief\" at 2:108 — carries the root كفر. The others come from different roots."},{"type":"multiple_choice","question":"What does كَفَّارٍ mean?","options":["ungrateful","believe","surely, is a sign","so that they may taste"],"correct":0,"explanation":"\"ungrateful\", from the word-by-word gloss at 2:276."},{"type":"fill_blank","question":"Type the root of كُفَّارًا in Arabic (three letters).","correct":"كفر","explanation":"كفر. Diacritics are ignored when checking, so ك ف ر is enough."}]', '["root-Aty"]', 15);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes) VALUES ('root-byn', 'The root بين (ب ي ن)', 'grammar', 1, '{"explanation":"The root بين occurs 523 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 29 distinct glossed words, tagged in the corpus as LOC, V, N, ADJ, in verb forms II, V, IV, X. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"تَّبَيَّنَ","transliteration":"","meaning":"has become distinct","rule":"2:256"},{"arabic":"يُبَيِّنُهَا","transliteration":"","meaning":"He makes them clear","rule":"2:230"},{"arabic":"بَيْنَهُم","transliteration":"","meaning":"between themselves","rule":"2:232"},{"arabic":"بَيِّنَـٰتٍۢ","transliteration":"","meaning":"clear","rule":"2:99"},{"arabic":"بِٱلْبَيِّنَـٰتِ","transliteration":"","meaning":"with [the] clear signs","rule":"2:92"},{"arabic":"وَيُبَيِّنُ","transliteration":"","meaning":"And He makes clear","rule":"2:221"}],"rules":[{"name":"Words on بين","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["تَّبَيَّنَ","يُبَيِّنُهَا","بَيْنَهُم","بَيِّنَـٰتٍۢ","بِٱلْبَيِّنَـٰتِ","وَيُبَيِّنُ","بَّيْنَكُمْ","وَبَيْنَهُۥٓ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root بين?","options":["يَتَّخِذُوا۟","وَءَاثَارًۭا","أَمْرَهُم","تَّبَيَّنَ"],"correct":3,"explanation":"تَّبَيَّنَ — glossed \"has become distinct\" at 2:256 — carries the root بين. The others come from different roots."},{"type":"multiple_choice","question":"What does يُبَيِّنُهَا mean?","options":["(the) remembrance of Allah","(of) people","He makes them clear","and the god"],"correct":2,"explanation":"\"He makes them clear\", from the word-by-word gloss at 2:230."},{"type":"fill_blank","question":"Type the r