INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes) VALUES ('root-$yA', 'The root شيا (ش ي ا)', 'grammar', 1, '{"explanation":"The root شيا occurs 519 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 12 distinct glossed words, tagged in the corpus as V, N. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"شَىْءٌۭ","transliteration":"","meaning":"anything","rule":"2:178"},{"arabic":"شَىْءٍۢ","transliteration":"","meaning":"thing","rule":"2:20"},{"arabic":"شَىْءٌ","transliteration":"","meaning":"(of) anything","rule":"3:128"},{"arabic":"شَآءَ","transliteration":"","meaning":"had willed","rule":"2:20"},{"arabic":"بِشَىْءٍۢ","transliteration":"","meaning":"with something","rule":"2:155"},{"arabic":"شَيْـًٔا","transliteration":"","meaning":"anything","rule":"2:229"}],"rules":[{"name":"Words on شيا","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["شَىْءٌۭ","شَىْءٍۢ","شَىْءٌ","شَآءَ","بِشَىْءٍۢ","شَيْـًٔا","يَشَآءُ","شَيْـًۭٔا"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root شيا?","options":["وَيَتَّخِذَهَا","ٱللَّهُ","شَىْءٌۭ","ٱللَّهُ"],"correct":2,"explanation":"شَىْءٌۭ — glossed \"anything\" at 2:178 — carries the root شيا. The others come from different roots."},{"type":"multiple_choice","question":"What does شَىْءٍۢ mean?","options":["the Command","thing","he brings","their partners"],"correct":1,"explanation":"\"thing\", from the word-by-word gloss at 2:20."},{"type":"fill_blank","question":"Type the root of شَىْءٌ in Arabic (three letters).","correct":"شيا","explanation":"شيا. Diacritics are ignored when checking, so ش ي ا is enough."}]', '["root-byn"]', 15);
