INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes) VALUES ('root-jEl', 'The root جعل (ج ع ل)', 'grammar', 2, '{"explanation":"The root جعل occurs 346 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 34 distinct glossed words, tagged in the corpus as V, N. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"لَجَعَلَكُمْ","transliteration":"","meaning":"He (would have) made you","rule":"5:48"},{"arabic":"وَلِنَجْعَلَكَ","transliteration":"","meaning":"and We will make you","rule":"2:259"},{"arabic":"جَعَلَكُمْ","transliteration":"","meaning":"(has) made you","rule":"6:165"},{"arabic":"وَيَجْعَلَ","transliteration":"","meaning":"and has placed","rule":"4:19"},{"arabic":"تَجْعَلُوا۟","transliteration":"","meaning":"set up","rule":"2:22"},{"arabic":"وَجَاعِلُ","transliteration":"","meaning":"and I will make","rule":"3:55"}],"rules":[{"name":"Words on جعل","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["لَجَعَلَكُمْ","وَلِنَجْعَلَكَ","جَعَلَكُمْ","وَيَجْعَلَ","تَجْعَلُوا۟","وَجَاعِلُ","تَجْعَلُونَهُۥ","ٱجْعَلْ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root جعل?","options":["لَجَعَلَكُمْ","أُخْتَهَا","أَجَلَ","أَبُوهُمْ"],"correct":0,"explanation":"لَجَعَلَكُمْ — glossed \"He (would have) made you\" at 5:48 — carries the root جعل. The others come from different roots."},{"type":"multiple_choice","question":"What does وَلِنَجْعَلَكَ mean?","options":["their (specified) term","and We will make you","come (to) us","you have taken"],"correct":1,"explanation":"\"and We will make you\", from the word-by-word gloss at 2:259."},{"type":"fill_blank","question":"Type the root of جَعَلَكُمْ in Arabic (three letters).","correct":"جعل","explanation":"جعل. Diacritics are ignored when checking, so ج ع ل is enough."}]', '["root-Eml"]', 15);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes) VALUES ('root-rHm', 'The root رحم (ر ح م)', 'grammar', 2, '{"explanation":"The root رحم occurs 339 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 26 distinct glossed words, tagged in the corpus as ADJ, N, V. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"رَّحِيمًۭا","transliteration":"","meaning":"Most-Merciful","rule":"4:23"},{"arabic":"أَرْحَامِهِنَّ","transliteration":"","meaning":"their wombs","rule":"2:228"},{"arabic":"ٱلْأَرْحَامِ","transliteration":"","meaning":"the wombs","rule":"3:6"},{"arabic":"رَحْمَةٍۢ","transliteration":"","meaning":"(of) Mercy","rule":"3:159"},{"arabic":"وَرَحْمَةًۭ","transliteration":"","meaning":"and mercy","rule":"4:96"},{"arabic":"ٱلرَّحِيمُ","transliteration":"","meaning":"the Most Merciful","rule":"2:37"}],"rules":[{"name":"Words on رحم","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["رَّحِيمًۭا","أَرْحَامِهِنَّ","ٱلْأَرْحَامِ","رَحْمَةٍۢ","وَرَحْمَةًۭ","ٱلرَّحِيمُ","رَحْمَةِ","رَحْمَتَ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root رحم?","options":["فَأَخَذْتُهُمْ","رَّحِيمًۭا","أَشَدُّ","تُؤْمِنُونَ"],"correct":1,"explanation":"رَّحِيمًۭا — glossed \"Most-Merciful\" at 4:23 — carries the root رحم. The others come from different roots."},{"type":"multiple_choice","question":"What does أَرْحَامِهِنَّ mean?","options":["their wombs","he came (to) it","and Allah will turn (in Mercy)","and the mankind"],"correct":0,"explanation":"\"their wombs\", from the word-by-word gloss at 2:228."},{"type":"fill_blank","question":"Type the root of ٱلْأَرْحَامِ in Arabic (three letters).","correct":"رحم","explanation":"رحم. Diacritics are ignored when checking, so ر ح م is enough."}]', '["root-jEl"]', 15);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes) VALUES ('root-rAy', 'The root راي (ر ا ي)', 'grammar', 2, '{"explanation":"The root راي occurs 328 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 37 distinct glossed words, tagged in the corpus as V, N, in verb forms IV, III, VI. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"وَرَأَوُا۟","transliteration":"","meaning":"and they will see","rule":"2:166"},{"arabic":"أَرِنِى","transliteration":"","meaning":"show me","rule":"2:260"},{"arabic":"رَأَيْتُمُوهُ","transliteration":"","meaning":"you have seen it","rule":"3:143"},{"arabic":"أَرِنِىٓ","transliteration":"","meaning":"Show me","rule":"7:143"},{"arabic":"نُرِىٓ","transliteration":"","meaning":"We show(ed)","rule":"6:75"},{"arabic":"تَرَ","transliteration":"","meaning":"you see","rule":"2:243"}],"rules":[{"name":"Words on راي","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["وَرَأَوُا۟","أَرِنِى","رَأَيْتُمُوهُ","أَرِنِىٓ","نُرِىٓ","تَرَ","تَرَىٰ","يَرَوْنَهُم"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root راي?","options":["أَمْرَهُمْ","وَرَأَوُا۟","ٱللَّهُ","أَبِى"],"correct":1,"explanation":"وَرَأَوُا۟ — glossed \"and they will see\" at 2:166 — carries the root راي. The others come from different roots."},{"type":"multiple_choice","question":"What does أَرِنِى mean?","options":["show me","comes (to) it","brought forth","surely, (would) have believed"],"correct":0,"explanation":"\"show me\", from the word-by-word gloss at 2:260."},{"type":"fill_blank","question":"Type the root of رَأَيْتُمُوهُ in Arabic (three letters).","correct":"راي","explanation":"راي. Diacritics are ignored when checking, so ر ا ي is enough."}]', '["root-rHm"]', 15);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes) VALUES ('root-ktb', 'The root كتب (ك ت ب)', 'grammar', 2, '{"explanation":"The root كتب occurs 319 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 23 distinct glossed words, tagged in the corpus as N, V, ADJ, in verb forms III, VIII. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"كَاتِبٌ","transliteration":"","meaning":"a scribe","rule":"2:282"},{"arabic":"فَٱكْتُبُوهُ","transliteration":"","meaning":"then write it","rule":"2:282"},{"arabic":"وَٱلْكِتَـٰبِ","transliteration":"","meaning":"and the Book","rule":"2:177"},{"arabic":"كَاتِبًۭا","transliteration":"","meaning":"a scribe","rule":"2:283"},{"arabic":"كَاتِبٌۢ","transliteration":"","meaning":"a scribe","rule":"2:282"},{"arabic":"كَاتِبٌۭ","transliteration":"","meaning":"(the) scribe","rule":"2:282"}],"rules":[{"name":"Words on كتب","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["كَاتِبٌ","فَٱكْتُبُوهُ","وَٱلْكِتَـٰبِ","كَاتِبًۭا","كَاتِبٌۢ","كَاتِبٌۭ","كَتَبَ","تَكْتُبُوهُ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root كتب?","options":["ءَايَةٌۭ","ٱلشَّجَرِ","كَاتِبٌ","يَتَّخِذُونَكَ"],"correct":2,"explanation":"كَاتِبٌ — glossed \"a scribe\" at 2:282 — carries the root كتب. The others come from different roots."},{"type":"multiple_choice","question":"What does فَٱكْتُبُوهُ mean?","options":["they come to you","then write it","associate partners (with Him)","god"],"correct":1,"explanation":"\"then write it\", from the word-by-word gloss at 2:282."},{"type":"fill_blank","question":"Type the root of وَٱلْكِتَـٰبِ in Arabic (three letters).","correct":"كتب","explanation":"كتب. Diacritics are ignored when checking, so ك ت ب is enough."}]', '["root-rAy"]', 15);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes) VALUES ('root-hdy', 'The root هدي (ه د ي)', 'grammar', 2, '{"explanation":"The root هدي occurs 316 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 32 distinct glossed words, tagged in the corpus as V, N, in verb form VIII. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"هَدَىٰكُمْ","transliteration":"","meaning":"He guided you","rule":"2:185"},{"arabic":"ٱلْمُهْتَدُونَ","transliteration":"","meaning":"(are) the guided ones","rule":"2:157"},{"arabic":"يَهْتَدُونَ","transliteration":"","meaning":"were they guided","rule":"2:170"},{"arabic":"بِٱلْهُدَىٰ","transliteration":"","meaning":"for [the] guidance","rule":"2:16"},{"arabic":"ٱلْهَدْىَ","transliteration":"","meaning":"the sacrificial animals","rule":"5:2"},{"arabic":"وَيَهْدِيَكُمْ","transliteration":"","meaning":"and to guide you","rule":"4:26"}],"rules":[{"name":"Words on هدي","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["هَدَىٰكُمْ","ٱلْمُهْتَدُونَ","يَهْتَدُونَ","بِٱلْهُدَىٰ","ٱلْهَدْىَ","وَيَهْدِيَكُمْ","ٱلْهَدْىُ","تَهْدُوا۟"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root هدي?","options":["هَدَىٰكُمْ","أَشْرَكْتُمُونِ","ٱللَّهِ","وَإِخْوَٰنُكُمْ"],"correct":0,"explanation":"هَدَىٰكُمْ — glossed \"He guided you\" at 2:185 — carries the root هدي. The others come from different roots."},{"type":"multiple_choice","question":"What does ٱلْمُهْتَدُونَ mean?","options":["any","your gods","(are) the guided ones","(are) more intense"],"correct":2,"explanation":"\"(are) the guided ones\", from the word-by-word gloss at 2:157."},{"type":"fill_blank","question":"Type the root of يَهْتَدُونَ in Arabic (three letters).","correct":"هدي","explanation":"هدي. Diacritics are ignored when checking, so ه د ي is enough."}]', '["root-ktb"]', 15);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes) VALUES ('root-Zlm', 'The root ظلم (ظ ل م)', 'grammar', 2, '{"explanation":"The root ظلم occurs 315 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 33 distinct glossed words, tagged in the corpus as N, V, ADJ, in verb form IV. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"تَظْلِمُونَ","transliteration":"","meaning":"wrong","rule":"2:279"},{"arabic":"يَظْلِمُونَ","transliteration":"","meaning":"doing wrong","rule":"2:57"},{"arabic":"ظَالِمِىٓ","transliteration":"","meaning":"(while) they (were) wronging","rule":"4:97"},{"arabic":"ٱلظَّالِمِ","transliteration":"","meaning":"[the] oppressor(s)","rule":"4:75"},{"arabic":"ٱلظُّلُمَـٰتِ","transliteration":"","meaning":"[the] darkness","rule":"2:257"},{"arabic":"ظُلُمَـٰتٍۢ","transliteration":"","meaning":"darkness[es]","rule":"2:17"}],"rules":[{"name":"Words on ظلم","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["تَظْلِمُونَ","يَظْلِمُونَ","ظَالِمِىٓ","ٱلظَّالِمِ","ٱلظُّلُمَـٰتِ","ظُلُمَـٰتٍۢ","أَظْلَمَ","ظَلَمْتُمْ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root ظلم?","options":["أَشَدَّ","ٱلْأُمُورِ","تَظْلِمُونَ","ٱللَّهِ"],"correct":2,"explanation":"تَظْلِمُونَ — glossed \"wrong\" at 2:279 — carries the root ظلم. The others come from different roots."},{"type":"multiple_choice","question":"What does يَظْلِمُونَ mean?","options":["and the tree","doing wrong","we believe[d]","they brought"],"correct":1,"explanation":"\"doing wrong\", from the word-by-word gloss at 2:57."},{"type":"fill_blank","question":"Type the root of ظَالِمِىٓ in Arabic (three letters).","correct":"ظلم","explanation":"ظلم. Diacritics are ignored when checking, so ظ ل م is enough."}]', '["root-hdy"]', 15);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes) VALUES ('root-nfs', 'The root نفس (ن ف س)', 'grammar', 2, '{"explanation":"The root نفس occurs 298 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 29 distinct glossed words, tagged in the corpus as N, V, in verb forms V, VI. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"وَأَنفُسَنَا","transliteration":"","meaning":"and ourselves","rule":"3:61"},{"arabic":"وَٱلْأَنفُسِ","transliteration":"","meaning":"and [the] lives","rule":"2:155"},{"arabic":"وَأَنفُسِكُمْ","transliteration":"","meaning":"and yourselves","rule":"3:186"},{"arabic":"لِنَفْسٍ","transliteration":"","meaning":"for a soul","rule":"3:145"},{"arabic":"أَنفُسِكُمُ","transliteration":"","meaning":"yourselves","rule":"3:168"},{"arabic":"وَأَنفُسَكُمْ","transliteration":"","meaning":"and yourselves","rule":"3:61"}],"rules":[{"name":"Words on نفس","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["وَأَنفُسَنَا","وَٱلْأَنفُسِ","وَأَنفُسِكُمْ","لِنَفْسٍ","أَنفُسِكُمُ","وَأَنفُسَكُمْ","أَنفُسِكُمْ","أَنفُسَهُم"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root نفس?","options":["ٱلشَّرَابُ","ٱلْأَوَّلِينَ","وَأَنفُسَنَا","فَكُلَا"],"correct":2,"explanation":"وَأَنفُسَنَا — glossed \"and ourselves\" at 3:61 — carries the root نفس. The others come from different roots."},{"type":"multiple_choice","question":"What does وَٱلْأَنفُسِ mean?","options":["(by the) family","So seized them","(is) a Reminder","and [the] lives"],"correct":3,"explanation":"\"and [the] lives\", from the word-by-word gloss at 2:155."},{"type":"fill_blank","question":"Type the root of وَأَنفُسِكُمْ in Arabic (three letters).","correct":"نفس","explanation":"نفس. Diacritics are ignored when checking, so ن ف س is enough."}]', '["root-Zlm"]', 15);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes) VALUES ('root-qbl', 'The root قبل (ق ب ل)', 'grammar', 2, '{"explanation":"The root قبل occurs 294 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 30 distinct glossed words, tagged in the corpus as N, V, LOC, T, in verb forms V, IV, VI, X. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"قَبْلِنَا","transliteration":"","meaning":"before us","rule":"2:286"},{"arabic":"يُقْبَلُ","transliteration":"","meaning":"will be accepted","rule":"2:48"},{"arabic":"قَبْلُ","transliteration":"","meaning":"before","rule":"2:25"},{"arabic":"قَبْلِى","transliteration":"","meaning":"before me","rule":"3:183"},{"arabic":"قَبْلِكُم","transliteration":"","meaning":"before you","rule":"2:214"},{"arabic":"قَبْلِهِم","transliteration":"","meaning":"before them","rule":"2:118"}],"rules":[{"name":"Words on قبل","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["قَبْلِنَا","يُقْبَلُ","قَبْلُ","قَبْلِى","قَبْلِكُم","قَبْلِهِم","قَبْلِكَ","قِبْلَتَهُمْ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root قبل?","options":["يَشْهَدُ","يَأْتِيَكُمَا","قَبْلِنَا","وَأَخَوَٰتُكُم"],"correct":2,"explanation":"قَبْلِنَا — glossed \"before us\" at 2:286 — carries the root قبل. The others come from different roots."},{"type":"multiple_choice","question":"What does يُقْبَلُ mean?","options":["your father","by the leave","then seized them","will be accepted"],"correct":3,"explanation":"\"will be accepted\", from the word-by-word gloss at 2:48."},{"type":"fill_blank","question":"Type the root of قَبْلُ in Arabic (three letters).","correct":"قبل","explanation":"قبل. Diacritics are ignored when checking, so ق ب ل is enough."}]', '["root-nfs"]', 15);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes) VALUES ('root-nzl', 'The root نزل (ن ز ل)', 'grammar', 2, '{"explanation":"The root نزل occurs 293 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 22 distinct glossed words, tagged in the corpus as V, N, in verb forms IV, II, V. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"أَنزَلَ","transliteration":"","meaning":"has revealed","rule":"2:90"},{"arabic":"أُنزِلَتِ","transliteration":"","meaning":"was revealed","rule":"3:65"},{"arabic":"يُنَزِّلْ","transliteration":"","meaning":"He sent down","rule":"3:151"},{"arabic":"مُنزَلِينَ","transliteration":"","meaning":"[the ones] sent down","rule":"3:124"},{"arabic":"أَنزَلْنَآ","transliteration":"","meaning":"We revealed","rule":"2:99"},{"arabic":"تُنَزَّلَ","transliteration":"","meaning":"(was) revealed","rule":"3:93"}],"rules":[{"name":"Words on نزل","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["أَنزَلَ","أُنزِلَتِ","يُنَزِّلْ","مُنزَلِينَ","أَنزَلْنَآ","تُنَزَّلَ","أُنزِلَ","تُنَزِّلَ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root نزل?","options":["تَأْتِهِم","ٱللَّهُ","يُؤْفَكُونَ","أَنزَلَ"],"correct":3,"explanation":"أَنزَلَ — glossed \"has revealed\" at 2:90 — carries the root نزل. The others come from different roots."},{"type":"multiple_choice","question":"What does أُنزِلَتِ mean?","options":["Allah wills","(to) Allah","the later ones","was revealed"],"correct":3,"explanation":"\"was revealed\", from the word-by-word gloss at 3:65."},{"type":"fill_blank","question":"Type the root of يُنَزِّلْ in Arabic (three letters).","correct":"نزل","explanation":"نزل. Diacritics are ignored when checking, so ن ز ل is enough."}]', '["root-qbl"]', 15);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes) VALUES ('root-*kr', 'The root ذكر (ذ ك ر)', 'grammar', 2, '{"explanation":"The root ذكر occurs 292 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 37 distinct glossed words, tagged in the corpus as V, N, ADJ, in verb forms V, II, VIII. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"ٱذْكُرْ","transliteration":"","meaning":"Remember","rule":"5:110"},{"arabic":"يَتَذَكَّرُونَ","transliteration":"","meaning":"take heed","rule":"2:221"},{"arabic":"ذَكَرُوا۟","transliteration":"","meaning":"they remember","rule":"3:135"},{"arabic":"فَٱذْكُرُوا۟","transliteration":"","meaning":"then remember","rule":"2:198"},{"arabic":"ذُكِّرُوا۟","transliteration":"","meaning":"they were reminded","rule":"5:13"},{"arabic":"يُذْكَرَ","transliteration":"","meaning":"be mentioned","rule":"2:114"}],"rules":[{"name":"Words on ذكر","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["ٱذْكُرْ","يَتَذَكَّرُونَ","ذَكَرُوا۟","فَٱذْكُرُوا۟","ذُكِّرُوا۟","يُذْكَرَ","ذُكِرَ","وَٱذْكُرُوا۟"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root ذكر?","options":["شَيْـًۭٔا","أَخَذْنَـٰهُم","ٱذْكُرْ","يَأْذَنَ"],"correct":2,"explanation":"ٱذْكُرْ — glossed \"Remember\" at 5:110 — carries the root ذكر. The others come from different roots."},{"type":"multiple_choice","question":"What does يَتَذَكَّرُونَ mean?","options":["take heed","came to them","they bring","its preparation"],"correct":0,"explanation":"\"take heed\", from the word-by-word gloss at 2:221."},{"type":"fill_blank","question":"Type the root of ذَكَرُوا۟ in Arabic (three letters).","correct":"ذكر","explanation":"ذكر. Diacritics are ignored when checking, so ذ ك ر is enough."}]', '["root-nzl"]', 15);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes) VALUES ('root-Hqq', 'The root حقق (ح ق ق)', 'grammar', 2, '{"explanation":"The root حقق occurs 287 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 14 distinct glossed words, tagged in the corpus as N, ADJ, V, in verb forms X, IV. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"بِٱلْحَقِّ","transliteration":"","meaning":"with the truth","rule":"2:71"},{"arabic":"أَحَقُّ","transliteration":"","meaning":"(have) better right","rule":"2:228"},{"arabic":"حَقَّ","transliteration":"","meaning":"(as it has the) right","rule":"2:121"},{"arabic":"ٱلْحَقِّ","transliteration":"","meaning":"[the] right","rule":"2:61"},{"arabic":"ٱلْحَقَّ","transliteration":"","meaning":"the Truth","rule":"2:42"},{"arabic":"حَقًّا","transliteration":"","meaning":"a duty","rule":"2:180"}],"rules":[{"name":"Words on حقق","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["بِٱلْحَقِّ","أَحَقُّ","حَقَّ","ٱلْحَقِّ","ٱلْحَقَّ","حَقًّا","حَقًّۭا","بِحَقٍّ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root حقق?","options":["إِثْمٌۭ","أَشْتَاتًۭا","بِٱلْحَقِّ","ٱللَّهُ"],"correct":2,"explanation":"بِٱلْحَقِّ — glossed \"with the truth\" at 2:71 — carries the root حقق. The others come from different roots."},{"type":"multiple_choice","question":"What does أَحَقُّ mean?","options":["(have) better right","harmed","So Allah seized them","Do you commit"],"correct":0,"explanation":"\"(have) better right\", from the word-by-word gloss at 2:228."},{"type":"fill_blank","question":"Type the root of حَقَّ in Arabic (three letters).","correct":"حقق","explanation":"حقق. Diacritics are ignored when checking, so ح ق ق is enough."}]', '["root-*kr"]', 15);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes) VALUES ('root-k*b', 'The root كذب (ك ذ ب)', 'grammar', 2, '{"explanation":"The root كذب occurs 282 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 22 distinct glossed words, tagged in the corpus as V, N, ADJ, in verb form II. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"كَذِبًۭا","transliteration":"","meaning":"a lie","rule":"6:144"},{"arabic":"لِلْكَذِبِ","transliteration":"","meaning":"to falsehood","rule":"5:41"},{"arabic":"كَذَّبُوا۟","transliteration":"","meaning":"They denied","rule":"3:11"},{"arabic":"لَكَـٰذِبُونَ","transliteration":"","meaning":"certainly are liars","rule":"6:28"},{"arabic":"كَذَبُوا۟","transliteration":"","meaning":"they lied","rule":"6:24"},{"arabic":"كَذَّبْتُمْ","transliteration":"","meaning":"you denied","rule":"2:87"}],"rules":[{"name":"Words on كذب","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["كَذِبًۭا","لِلْكَذِبِ","كَذَّبُوا۟","لَكَـٰذِبُونَ","كَذَبُوا۟","كَذَّبْتُمْ","كُذِّبَ","نُكَذِّبَ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root كذب?","options":["يَأْتِ","وَذَكِّرْهُم","كَذِبًۭا","وَّءَامَنُوا۟"],"correct":2,"explanation":"كَذِبًۭا — glossed \"a lie\" at 6:144 — carries the root كذب. The others come from different roots."},{"type":"multiple_choice","question":"What does لِلْكَذِبِ mean?","options":["drinks","painful","Bring us","to falsehood"],"correct":3,"explanation":"\"to falsehood\", from the word-by-word gloss at 5:41."},{"type":"fill_blank","question":"Type the root of كَذَّبُوا۟ in Arabic (three letters).","correct":"كذب","explanation":"كذب. Diacritics are ignored when checking, so ك ذ ب is enough."}]', '["root-Hqq"]', 15);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes) VALUES ('root-jyA', 'The root جيا (ج ي ا)', 'grammar', 2, '{"explanation":"The root جيا occurs 278 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 26 distinct glossed words, tagged in the corpus as V. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"جِئْتَ","transliteration":"","meaning":"you have come","rule":"2:71"},{"arabic":"جَآءَهُۥ","transliteration":"","meaning":"comes to him","rule":"2:275"},{"arabic":"وَجَآءَهُمُ","transliteration":"","meaning":"and came to them","rule":"3:86"},{"arabic":"جَآءَتْهُمْ","transliteration":"","meaning":"came to them","rule":"5:32"},{"arabic":"جَآءَهُم","transliteration":"","meaning":"came to them","rule":"2:89"},{"arabic":"جِئْتَهُم","transliteration":"","meaning":"you came to them","rule":"5:110"}],"rules":[{"name":"Words on جيا","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["جِئْتَ","جَآءَهُۥ","وَجَآءَهُمُ","جَآءَتْهُمْ","جَآءَهُم","جِئْتَهُم","جَآءَكَ","وَجِئْتُكُم"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root جيا?","options":["ٱلتَّذْكِرَةِ","جِئْتَ","وَيَشْتَرُونَ","شَأْنٌۭ"],"correct":1,"explanation":"جِئْتَ — glossed \"you have come\" at 2:71 — carries the root جيا. The others come from different roots."},{"type":"multiple_choice","question":"What does جَآءَهُۥ mean?","options":["believed","witnessed","they spread","comes to him"],"correct":3,"explanation":"\"comes to him\", from the word-by-word gloss at 2:275."},{"type":"fill_blank","question":"Type the root of وَجَآءَهُمُ in Arabic (three letters).","correct":"جيا","explanation":"جيا. Diacritics are ignored when checking, so ج ي ا is enough."}]', '["root-k*b"]', 15);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes) VALUES ('root-Ebd', 'The root عبد (ع ب د)', 'grammar', 2, '{"explanation":"The root عبد occurs 275 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 33 distinct glossed words, tagged in the corpus as V, N, ADJ, in verb form II. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"نَعْبُدَ","transliteration":"","meaning":"we worship","rule":"3:64"},{"arabic":"عِبَادِى","transliteration":"","meaning":"My servants","rule":"2:186"},{"arabic":"عِبَادِهِۦ","transliteration":"","meaning":"His servants","rule":"2:90"},{"arabic":"لِّلْعَبِيدِ","transliteration":"","meaning":"to (His) slaves","rule":"3:182"},{"arabic":"أَعْبُدُ","transliteration":"","meaning":"I worship","rule":"10:104"},{"arabic":"وَلَعَبْدٌۭ","transliteration":"","meaning":"and a bondman","rule":"2:221"}],"rules":[{"name":"Words on عبد","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["نَعْبُدَ","عِبَادِى","عِبَادِهِۦ","لِّلْعَبِيدِ","أَعْبُدُ","وَلَعَبْدٌۭ","لِيَعْبُدُوٓا۟","۞ وَٱعْبُدُوا۟"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root عبد?","options":["ٱللَّهُ","نَعْبُدَ","ذَكَرْتَ","أُوتُوا۟"],"correct":1,"explanation":"نَعْبُدَ — glossed \"we worship\" at 3:64 — carries the root عبد. The others come from different roots."},{"type":"multiple_choice","question":"What does عِبَادِى mean?","options":["and you believe","My servants","Allah disliked","testify"],"correct":1,"explanation":"\"My servants\", from the word-by-word gloss at 2:186."},{"type":"fill_blank","question":"Type the root of عِبَادِهِۦ in Arabic (three letters).","correct":"عبد","explanation":"عبد. Diacritics are ignored when checking, so ع ب د is enough."}]', '["root-jyA"]', 15);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes) VALUES ('root-Ax*', 'The root اخذ (ا خ ذ)', 'grammar', 2, '{"explanation":"The root اخذ occurs 273 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 45 distinct glossed words, tagged in the corpus as V, N, in verb forms VIII, III. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"وَأَخَذْتُمْ","transliteration":"","meaning":"and take","rule":"3:81"},{"arabic":"يَتَّخِذِ","transliteration":"","meaning":"take","rule":"3:28"},{"arabic":"وَأَخَذْنَ","transliteration":"","meaning":"and they have taken","rule":"4:21"},{"arabic":"يَتَّخِذُونَ","transliteration":"","meaning":"take","rule":"4:139"},{"arabic":"تَأْخُذُوا۟","transliteration":"","meaning":"you take (back)","rule":"2:229"},{"arabic":"وَٱتَّخِذُوا۟","transliteration":"","meaning":"and (said), \"Take","rule":"2:125"}],"rules":[{"name":"Words on اخذ","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["وَأَخَذْتُمْ","يَتَّخِذِ","وَأَخَذْنَ","يَتَّخِذُونَ","تَأْخُذُوا۟","وَٱتَّخِذُوا۟","فَأَخَذَتْهُمُ","وَيَتَّخِذَ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root اخذ?","options":["وَأَخَذْتُمْ","ذُكِرَ","ذِكْرَىٰ","مَّذْكُورًا"],"correct":0,"explanation":"وَأَخَذْتُمْ — glossed \"and take\" at 3:81 — carries the root اخذ. The others come from different roots."},{"type":"multiple_choice","question":"What does يَتَّخِذِ mean?","options":["associated partners (with Him)","(of) each point of sunrise","take","(the) masajid of Allah"],"correct":2,"explanation":"\"take\", from the word-by-word gloss at 3:28."},{"type":"fill_blank","question":"Type the root of وَأَخَذْنَ in Arabic (three letters).","correct":"اخذ","explanation":"اخذ. Diacritics are ignored when checking, so ا خ ذ is enough."}]', '["root-Ebd"]', 15);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes) VALUES ('root-xlq', 'The root خلق (خ ل ق)', 'grammar', 2, '{"explanation":"The root خلق occurs 261 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 35 distinct glossed words, tagged in the corpus as V, N, ADJ, in verb forms II, VIII. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"خَلَقَهُمْ","transliteration":"","meaning":"He created them","rule":"11:119"},{"arabic":"خَلْقٍۢ","transliteration":"","meaning":"a creation","rule":"13:5"},{"arabic":"خَلَقْتَ","transliteration":"","meaning":"You have created","rule":"3:191"},{"arabic":"بِخَلْقٍۢ","transliteration":"","meaning":"a creation","rule":"14:19"},{"arabic":"خَلَقَكُم","transliteration":"","meaning":"created you","rule":"4:1"},{"arabic":"خَلَقْتَنِى","transliteration":"","meaning":"You created me","rule":"7:12"}],"rules":[{"name":"Words on خلق","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["خَلَقَهُمْ","خَلْقٍۢ","خَلَقْتَ","بِخَلْقٍۢ","خَلَقَكُم","خَلَقْتَنِى","خَلْقِ","خَلَـٰقٍۢ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root خلق?","options":["خَلَقَهُمْ","ءَامَنَّا","شِئْنَا","وَذِكْرَىٰ"],"correct":0,"explanation":"خَلَقَهُمْ — glossed \"He created them\" at 11:119 — carries the root خلق. The others come from different roots."},{"type":"multiple_choice","question":"What does خَلْقٍۢ mean?","options":["let him believe","Our command","a creation","and the ear"],"correct":2,"explanation":"\"a creation\", from the word-by-word gloss at 13:5."},{"type":"fill_blank","question":"Type the root of خَلَقْتَ in Arabic (three letters).","correct":"خلق","explanation":"خلق. Diacritics are ignored when checking, so خ ل ق is enough."}]', '["root-Ax*"]', 15);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes) VALUES ('root-wqy', 'The root وقي (و ق ي)', 'grammar', 2, '{"explanation":"The root وقي occurs 258 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 26 distinct glossed words, tagged in the corpus as N, V, in verb form VIII. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"وَٱتَّقَىٰ","transliteration":"","meaning":"and fears (Allah)","rule":"3:76"},{"arabic":"وَلْيَتَّقِ","transliteration":"","meaning":"and let him fear","rule":"2:282"},{"arabic":"يَتَّقُونَ","transliteration":"","meaning":"(become) righteous","rule":"2:187"},{"arabic":"ٱلتَّقْوَىٰ","transliteration":"","meaning":"(is) righteousness","rule":"2:197"},{"arabic":"تُقَىٰةًۭ","transliteration":"","meaning":"(as) a precaution","rule":"3:28"},{"arabic":"فَقِنَا","transliteration":"","meaning":"so save us","rule":"3:191"}],"rules":[{"name":"Words on وقي","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["وَٱتَّقَىٰ","وَلْيَتَّقِ","يَتَّقُونَ","ٱلتَّقْوَىٰ","تُقَىٰةًۭ","فَقِنَا","ٱتَّقَوْا۟","وَٱتَّقَوْا۟"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root وقي?","options":["وَٱتَّقَىٰ","فَيُؤْخَذُ","أَتَىٰكُمْ","ءَاثِمًا"],"correct":0,"explanation":"وَٱتَّقَىٰ — glossed \"and fears (Allah)\" at 3:76 — carries the root وقي. The others come from different roots."},{"type":"multiple_choice","question":"What does وَلْيَتَّقِ mean?","options":["bring","and let him fear","Bring","(the) people"],"correct":1,"explanation":"\"and let him fear\", from the word-by-word gloss at 2:282."},{"type":"fill_blank","question":"Type the root of يَتَّقُونَ in Arabic (three letters).","correct":"وقي","explanation":"وقي. Diacritics are ignored when checking, so و ق ي is enough."}]', '["root-xlq"]', 15);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes) VALUES ('root-Axr', 'The root اخر (ا خ ر)', 'grammar', 2, '{"explanation":"The root اخر occurs 250 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 23 distinct glossed words, tagged in the corpus as N, ADJ, V, T, in verb forms V, II, X. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"ءَاخِرَهُۥ","transliteration":"","meaning":"(at) its end","rule":"3:72"},{"arabic":"ٱلْـَٔاخِرِ","transliteration":"","meaning":"[the] Last","rule":"2:8"},{"arabic":"وَءَاخِرِنَا","transliteration":"","meaning":"and last of us","rule":"5:114"},{"arabic":"وَٱلْـَٔاخِرَةُ","transliteration":"","meaning":"and the Hereafter","rule":"4:77"},{"arabic":"ٱلْـَٔاخِرَةِ","transliteration":"","meaning":"the Hereafter","rule":"2:102"},{"arabic":"ٱلْأُخْرَىٰ","transliteration":"","meaning":"the other","rule":"2:282"}],"rules":[{"name":"Words on اخر","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["ءَاخِرَهُۥ","ٱلْـَٔاخِرِ","وَءَاخِرِنَا","وَٱلْـَٔاخِرَةُ","ٱلْـَٔاخِرَةِ","ٱلْأُخْرَىٰ","ءَاخَرِينَ","وَبِٱلْـَٔاخِرَةِ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root اخر?","options":["أَشْرَكُوٓا۟","بِٱلْأُفُقِ","ءَاخِرَهُۥ","وَيَأْمُرُونَ"],"correct":2,"explanation":"ءَاخِرَهُۥ — glossed \"(at) its end\" at 3:72 — carries the root اخر. The others come from different roots."},{"type":"multiple_choice","question":"What does ٱلْـَٔاخِرِ mean?","options":["[the] Last","And the believing men","(and) severe","Allah had willed"],"correct":0,"explanation":"\"[the] Last\", from the word-by-word gloss at 2:8."},{"type":"fill_blank","question":"Type the root of وَءَاخِرِنَا in Arabic (three letters).","correct":"اخر","explanation":"اخر. Diacritics are ignored when checking, so ا خ ر is enough."}]', '["root-wqy"]', 15);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes) VALUES ('root-Amr', 'The root امر (ا م ر)', 'grammar', 2, '{"explanation":"The root امر occurs 248 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 39 distinct glossed words, tagged in the corpus as V, N, ADJ, in verb form VIII. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"ٱلْأَمْرُ","transliteration":"","meaning":"the matter","rule":"2:210"},{"arabic":"يَأْمُرُكُم","transliteration":"","meaning":"orders you (to do) it","rule":"2:93"},{"arabic":"أَمَرْتَنِى","transliteration":"","meaning":"You commanded me","rule":"5:117"},{"arabic":"وَٱلْأَمْرُ","transliteration":"","meaning":"and the command","rule":"7:54"},{"arabic":"أَمَرَ","transliteration":"","meaning":"has ordered","rule":"2:27"},{"arabic":"وَيَأْمُرُكُم","transliteration":"","meaning":"and orders you","rule":"2:268"}],"rules":[{"name":"Words on امر","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["ٱلْأَمْرُ","يَأْمُرُكُم","أَمَرْتَنِى","وَٱلْأَمْرُ","أَمَرَ","وَيَأْمُرُكُم","وَيَأْمُرُونَ","أُمِرْتُ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root امر?","options":["لَيَأْتِيَنِّى","ٱلْأَمْرُ","شَيْطَـٰنًۭا","ٱللَّهُ"],"correct":1,"explanation":"ٱلْأَمْرُ — glossed \"the matter\" at 2:210 — carries the root امر. The others come from different roots."},{"type":"multiple_choice","question":"What does يَأْمُرُكُم mean?","options":["And remember","orders you (to do) it","associate","he ran away"],"correct":1,"explanation":"\"orders you (to do) it\", from the word-by-word gloss at 2:93."},{"type":"fill_blank","question":"Type the root of أَمَرْتَنِى in Arabic (three letters).","correct":"امر","explanation":"امر. Diacritics are ignored when checking, so ا م ر is enough."}]', '["root-Axr"]', 15);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes) VALUES ('root-nws', 'The root نوس (ن و س)', 'grammar', 2, '{"explanation":"The root نوس occurs 241 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 7 distinct glossed words, tagged in the corpus as N. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"وَٱلنَّاسِ","transliteration":"","meaning":"and the mankind","rule":"2:161"},{"arabic":"ٱلنَّاسَ","transliteration":"","meaning":"[the] people","rule":"2:44"},{"arabic":"لِّلنَّاسِ","transliteration":"","meaning":"for mankind","rule":"2:125"},{"arabic":"لِلنَّاسِ","transliteration":"","meaning":"to [the] people","rule":"2:83"},{"arabic":"ٱلنَّاسِ","transliteration":"","meaning":"the people","rule":"2:8"},{"arabic":"بِٱلنَّاسِ","transliteration":"","meaning":"(is) to [the] mankind","rule":"2:143"}],"rules":[{"name":"Words on نوس","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["وَٱلنَّاسِ","ٱلنَّاسَ","لِّلنَّاسِ","لِلنَّاسِ","ٱلنَّاسِ","بِٱلنَّاسِ","ٱلنَّاسُ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root نوس?","options":["وَأُخِذُوا۟","لِيُذِيقَهُم","وَٱلنَّاسِ","يَشَآءُ"],"correct":2,"explanation":"وَٱلنَّاسِ — glossed \"and the mankind\" at 2:161 — carries the root نوس. The others come from different roots."},{"type":"multiple_choice","question":"What does ٱلنَّاسَ mean?","options":["Allah gave them","the (one) mighty","[the] people","then (the) testimony"],"correct":2,"explanation":"\"[the] people\", from the word-by-word gloss at 2:44."},{"type":"fill_blank","question":"Type the root of لِّلنَّاسِ in Arabic (three letters).","correct":"نوس","explanation":"نوس. Diacritics are ignored when checking, so ن و س is enough."}]', '["root-Amr"]', 15);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes) VALUES ('root-bEd', 'The root بعد (ب ع د)', 'grammar', 2, '{"explanation":"The root بعد occurs 235 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 11 distinct glossed words, tagged in the corpus as N, T, ADJ, V, in verb forms IV, III. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"بَعِيدًۭا","transliteration":"","meaning":"great","rule":"3:30"},{"arabic":"بَعِيدًا","transliteration":"","meaning":"far away","rule":"4:116"},{"arabic":"بَعْدِهِۦٓ","transliteration":"","meaning":"after him","rule":"3:65"},{"arabic":"بَعْدِهِۦ","transliteration":"","meaning":"after him","rule":"2:51"},{"arabic":"بَعْدُ","transliteration":"","meaning":"after (that)","rule":"2:230"},{"arabic":"بَعْدِى","transliteration":"","meaning":"after me","rule":"2:133"}],"rules":[{"name":"Words on بعد","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["بَعِيدًۭا","بَعِيدًا","بَعْدِهِۦٓ","بَعْدِهِۦ","بَعْدُ","بَعْدِى","بَعْدِهِم","بَعْدَ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root بعد?","options":["ذَكَرَهُۥ","بَعِيدًۭا","أَشْرَكُوا۟","وَٱلشَّهْرَ"],"correct":1,"explanation":"بَعِيدًۭا — glossed \"great\" at 3:30 — carries the root بعد. The others come from different roots."},{"type":"multiple_choice","question":"What does بَعِيدًا mean?","options":["the Favors of Allah","painful","they (will) remain behind","far away"],"correct":3,"explanation":"\"far away\", from the word-by-word gloss at 4:116."},{"type":"fill_blank","question":"Type the root of بَعْدِهِۦٓ in Arabic (three letters).","correct":"بعد","explanation":"بعد. Diacritics are ignored when checking, so ب ع د is enough."}]', '["root-nws"]', 15);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes) VALUES ('root-gfr', 'The root غفر (غ ف ر)', 'grammar', 2, '{"explanation":"The root غفر occurs 234 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 29 distinct glossed words, tagged in the corpus as V, N, ADJ, in verb form X. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"وَٱلْمَغْفِرَةِ","transliteration":"","meaning":"and [the] forgiveness","rule":"2:221"},{"arabic":"فَيَغْفِرُ","transliteration":"","meaning":"Then, He will forgive","rule":"2:284"},{"arabic":"مَّغْفِرَةًۭ","transliteration":"","meaning":"forgiveness","rule":"2:268"},{"arabic":"وَمَغْفِرَةٌ","transliteration":"","meaning":"and (seeking) forgiveness","rule":"2:263"},{"arabic":"ٱغْفِرْ","transliteration":"","meaning":"forgive","rule":"3:147"},{"arabic":"فَٱغْفِرْ","transliteration":"","meaning":"so forgive","rule":"3:16"}],"rules":[{"name":"Words on غفر","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["وَٱلْمَغْفِرَةِ","فَيَغْفِرُ","مَّغْفِرَةًۭ","وَمَغْفِرَةٌ","ٱغْفِرْ","فَٱغْفِرْ","لَمَغْفِرَةٌۭ","نَّغْفِرْ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root غفر?","options":["ءَالَآءَ","مُؤْمِنٌۭ","ٱتَّخِذِى","وَٱلْمَغْفِرَةِ"],"correct":3,"explanation":"وَٱلْمَغْفِرَةِ — glossed \"and [the] forgiveness\" at 2:221 — carries the root غفر. The others come from different roots."},{"type":"multiple_choice","question":"What does فَيَغْفِرُ mean?","options":["Then, He will forgive","And an announcement","and you both eat","(is) mightier"],"correct":0,"explanation":"\"Then, He will forgive\", from the word-by-word gloss at 2:284."},{"type":"fill_blank","question":"Type the root of مَّغْفِرَةًۭ in Arabic (three letters).","correct":"غفر","explanation":"غفر. Diacritics are ignored when checking, so غ ف ر is enough."}]', '["root-bEd"]', 15);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes) VALUES ('root-wly', 'The root ولي (و ل ي)', 'grammar', 2, '{"explanation":"The root ولي occurs 232 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 31 distinct glossed words, tagged in the corpus as V, N, ADJ, in verb forms V, II. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"يَتَوَلَّىٰ","transliteration":"","meaning":"turns away","rule":"3:23"},{"arabic":"أَوْلِيَآءَ","transliteration":"","meaning":"(as) allies","rule":"3:28"},{"arabic":"وَلَّىٰهُمْ","transliteration":"","meaning":"(has) turned them","rule":"2:142"},{"arabic":"مَوَٰلِىَ","transliteration":"","meaning":"heirs","rule":"4:33"},{"arabic":"فَلَنُوَلِّيَنَّكَ","transliteration":"","meaning":"So We will surely turn you","rule":"2:144"},{"arabic":"يُوَلُّوكُمُ","transliteration":"","meaning":"they will turn (towards) you","rule":"3:111"}],"rules":[{"name":"Words on ولي","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["يَتَوَلَّىٰ","أَوْلِيَآءَ","وَلَّىٰهُمْ","مَوَٰلِىَ","فَلَنُوَلِّيَنَّكَ","يُوَلُّوكُمُ","وَلِيُّهُمَا","مَوْلَىٰنَا"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root ولي?","options":["يُذْهِبَنَّ","وَٱلْمُشْرِكِينَ","أَتَىٰهُمْ","يَتَوَلَّىٰ"],"correct":3,"explanation":"يَتَوَلَّىٰ — glossed \"turns away\" at 3:23 — carries the root ولي. The others come from different roots."},{"type":"multiple_choice","question":"What does أَوْلِيَآءَ mean?","options":["our land","the witnesses","to his father","(as) allies"],"correct":3,"explanation":"\"(as) allies\", from the word-by-word gloss at 3:28."},{"type":"fill_blank","question":"Type the root of وَلَّىٰهُمْ in Arabic (three letters).","correct":"ولي","explanation":"ولي. Diacritics are ignored when checking, so و ل ي is enough."}]', '["root-gfr"]', 15);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes) VALUES ('root-dEw', 'The root دعو (د ع و)', 'grammar', 2, '{"explanation":"The root دعو occurs 212 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 38 distinct glossed words, tagged in the corpus as V, N, in verb form VIII. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"تَدْعُونَآ","transliteration":"","meaning":"you call us","rule":"11:62"},{"arabic":"تَدْعُوهُمْ","transliteration":"","meaning":"you call them","rule":"7:193"},{"arabic":"دَعْوَىٰهُمْ","transliteration":"","meaning":"their plea","rule":"7:5"},{"arabic":"فَٱدْعُوهُ","transliteration":"","meaning":"so invoke Him","rule":"7:180"},{"arabic":"وَٱدْعُوا۟","transliteration":"","meaning":"and call","rule":"2:23"},{"arabic":"أَدْعُوٓا۟","transliteration":"","meaning":"I invite","rule":"12:108"}],"rules":[{"name":"Words on دعو","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["تَدْعُونَآ","تَدْعُوهُمْ","دَعْوَىٰهُمْ","فَٱدْعُوهُ","وَٱدْعُوا۟","أَدْعُوٓا۟","دَعْوَةُ","أَنَدْعُوا۟"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root دعو?","options":["ذَنۢبٍۢ","تَدْعُونَآ","ٱللَّهُ","ءَامِنُونَ"],"correct":1,"explanation":"تَدْعُونَآ — glossed \"you call us\" at 11:62 — carries the root دعو. The others come from different roots."},{"type":"multiple_choice","question":"What does تَدْعُوهُمْ mean?","options":["will forget","receive admonition","you call them","believe"],"correct":2,"explanation":"\"you call them\", from the word-by-word gloss at 7:193."},{"type":"fill_blank","question":"Type the root of دَعْوَىٰهُمْ in Arabic (three letters).","correct":"دعو","explanation":"دعو. Diacritics are ignored when checking, so د ع و is enough."}]', '["root-wly"]', 15);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes) VALUES ('root-Hkm', 'The root حكم (ح ك م)', 'grammar', 2, '{"explanation":"The root حكم occurs 210 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 29 distinct glossed words, tagged in the corpus as ADJ, V, N, in verb forms IV, VI, II. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"فَٱحْكُم","transliteration":"","meaning":"then judge","rule":"5:42"},{"arabic":"يُحَكِّمُونَكَ","transliteration":"","meaning":"they appoint you a judge","rule":"5:43"},{"arabic":"ٱلْحِكْمَةَ","transliteration":"","meaning":"[the] wisdom","rule":"2:269"},{"arabic":"يَحْكُمُ","transliteration":"","meaning":"will judge","rule":"2:113"},{"arabic":"وَٱلْحُكْمَ","transliteration":"","meaning":"and the wisdom","rule":"3:79"},{"arabic":"وَلْيَحْكُمْ","transliteration":"","meaning":"And let judge","rule":"5:47"}],"rules":[{"name":"Words on حكم","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["فَٱحْكُم","يُحَكِّمُونَكَ","ٱلْحِكْمَةَ","يَحْكُمُ","وَٱلْحُكْمَ","وَلْيَحْكُمْ","يَتَحَاكَمُوٓا۟","وَحَكَمًۭا"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root حكم?","options":["أَثَرِى","أَمِنتُمْ","فَٱحْكُم","إِخْوَتِكَ"],"correct":2,"explanation":"فَٱحْكُم — glossed \"then judge\" at 5:42 — carries the root حكم. The others come from different roots."},{"type":"multiple_choice","question":"What does يُحَكِّمُونَكَ mean?","options":["we have testified","surely (is) a witness","they appoint you a judge","For Allah"],"correct":2,"explanation":"\"they appoint you a judge\", from the word-by-word gloss at 5:43."},{"type":"fill_blank","question":"Type the root of ٱلْحِكْمَةَ in Arabic (three letters).","correct":"حكم","explanation":"حكم. Diacritics are ignored when checking, so ح ك م is enough."}]', '["root-dEw"]', 15);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes) VALUES ('root-mlk', 'The root ملك (م ل ك)', 'grammar', 2, '{"explanation":"The root ملك occurs 206 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 29 distinct glossed words, tagged in the corpus as N, V, PN, ADJ. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"يَمْلِكُ","transliteration":"","meaning":"has power","rule":"5:17"},{"arabic":"مَلِكًۭا","transliteration":"","meaning":"a king","rule":"2:246"},{"arabic":"مُّلُوكًۭا","transliteration":"","meaning":"kings","rule":"5:20"},{"arabic":"ٱلْمَلَـٰٓئِكَةِ","transliteration":"","meaning":"the angels","rule":"2:31"},{"arabic":"ٱلْمُلْكُ","transliteration":"","meaning":"the kingship","rule":"2:247"},{"arabic":"أَمْلِكُ","transliteration":"","meaning":"(have) power","rule":"5:25"}],"rules":[{"name":"Words on ملك","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["يَمْلِكُ","مَلِكًۭا","مُّلُوكًۭا","ٱلْمَلَـٰٓئِكَةِ","ٱلْمُلْكُ","أَمْلِكُ","مَلَكًۭا","مُّلْكًا"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root ملك?","options":["ٱللَّهِ","وَٱتَّخَذَ","يَمْلِكُ","فَٱذْهَبْ"],"correct":2,"explanation":"يَمْلِكُ — glossed \"has power\" at 5:17 — carries the root ملك. The others come from different roots."},{"type":"multiple_choice","question":"What does مَلِكًۭا mean?","options":["And Allah is sufficient","Then go","a king","and order"],"correct":2,"explanation":"\"a king\", from the word-by-word gloss at 2:246."},{"type":"fill_blank","question":"Type the root of مُّلُوكًۭا in Arabic (three letters).","correct":"ملك","explanation":"ملك. Diacritics are ignored when checking, so م ل ك is enough."}]', '["root-Hkm"]', 15);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes) VALUES ('root-End', 'The root عند (ع ن د)', 'grammar', 2, '{"explanation":"The root عند occurs 201 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 14 distinct glossed words, tagged in the corpus as LOC, N, ADJ. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"عِندِ","transliteration":"","meaning":"from","rule":"2:79"},{"arabic":"عِندَهَا","transliteration":"","meaning":"with her","rule":"3:37"},{"arabic":"عِندَهُمُ","transliteration":"","meaning":"with them","rule":"4:139"},{"arabic":"عِندَهُۥ","transliteration":"","meaning":"(that) he has","rule":"2:140"},{"arabic":"عِندِهِۦ","transliteration":"","meaning":"(of) Him","rule":"5:52"},{"arabic":"عِندَنَا","transliteration":"","meaning":"with us","rule":"3:156"}],"rules":[{"name":"Words on عند","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["عِندِ","عِندَهَا","عِندَهُمُ","عِندَهُۥ","عِندِهِۦ","عِندَنَا","عِندَهُۥٓ","عِندَ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root عند?","options":["ءَامَنَّا","عِندِ","تَأْوِيلِ","تَأْوِيلِ"],"correct":1,"explanation":"عِندِ — glossed \"from\" at 2:79 — carries the root عند. The others come from different roots."},{"type":"multiple_choice","question":"What does عِندَهَا mean?","options":["those who associate partners (with Allah)","(the) term","with her","my tracks"],"correct":2,"explanation":"\"with her\", from the word-by-word gloss at 3:37."},{"type":"fill_blank","question":"Type the root of عِندَهُمُ in Arabic (three letters).","correct":"عند","explanation":"عند. Diacritics are ignored when checking, so ع ن د is enough."}]', '["root-mlk"]', 15);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes) VALUES ('root-jnn', 'The root جنن (ج ن ن)', 'grammar', 2, '{"explanation":"The root جنن occurs 201 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 19 distinct glossed words, tagged in the corpus as N, PN, V. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"وَٱلْجِنِّ","transliteration":"","meaning":"and the jinn","rule":"6:112"},{"arabic":"وَجَنَّـٰتٌۭ","transliteration":"","meaning":"and Gardens","rule":"3:136"},{"arabic":"ٱلْجِنَّ","transliteration":"","meaning":"jinn","rule":"6:100"},{"arabic":"جَنَّـٰتِ","transliteration":"","meaning":"(to) Gardens","rule":"5:65"},{"arabic":"جَنَّـٰتٍۢ","transliteration":"","meaning":"(will be) Gardens","rule":"2:25"},{"arabic":"ٱلْجَنَّةُ","transliteration":"","meaning":"(is) Paradise","rule":"7:43"}],"rules":[{"name":"Words on جنن","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["وَٱلْجِنِّ","وَجَنَّـٰتٌۭ","ٱلْجِنَّ","جَنَّـٰتِ","جَنَّـٰتٍۢ","ٱلْجَنَّةُ","ٱلْجَنَّةَ","ٱلْجِنَّةِ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root جنن?","options":["أَشَقُّ","وَٱلْجِنِّ","ٱلْمَشْرِقِ","ٱللَّهُ"],"correct":1,"explanation":"وَٱلْجِنِّ — glossed \"and the jinn\" at 6:112 — carries the root جنن. The others come from different roots."},{"type":"multiple_choice","question":"What does وَجَنَّـٰتٌۭ mean?","options":["and the Command","my family","and Gardens","give"],"correct":2,"explanation":"\"and Gardens\", from the word-by-word gloss at 3:136."},{"type":"fill_blank","question":"Type the root of ٱلْجِنَّ in Arabic (three letters).","correct":"جنن","explanation":"جنن. Diacritics are ignored when checking, so ج ن ن is enough."}]', '["root-End"]', 15);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes) VALUES ('root-xyr', 'The root خير (خ ي ر)', 'grammar', 3, '{"explanation":"The root خير occurs 196 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 11 distinct glossed words, tagged in the corpus as N, ADJ, V, in verb forms VIII, V. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"خَيْرٍۢ","transliteration":"","meaning":"good","rule":"2:105"},{"arabic":"خَيْرَ","transliteration":"","meaning":"(the) best","rule":"2:197"},{"arabic":"خَيْرُ","transliteration":"","meaning":"(is the) best","rule":"3:54"},{"arabic":"ٱلْخَيْرِ","transliteration":"","meaning":"the good","rule":"3:104"},{"arabic":"خَيْرًا","transliteration":"","meaning":"good","rule":"2:180"},{"arabic":"ٱلْخَيْرَٰتِ","transliteration":"","meaning":"(to) the good","rule":"2:148"}],"rules":[{"name":"Words on خير","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["خَيْرٍۢ","خَيْرَ","خَيْرُ","ٱلْخَيْرِ","خَيْرًا","ٱلْخَيْرَٰتِ","ٱلْخَيْرُ","خَيْرًۭا"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root خير?","options":["خَيْرٍۢ","أَتَتَّخِذُ","تَتَّخِذُونَ","ذَهَابٍۭ"],"correct":0,"explanation":"خَيْرٍۢ — glossed \"good\" at 2:105 — carries the root خير. The others come from different roots."},{"type":"multiple_choice","question":"What does خَيْرَ mean?","options":["And take for yourselves","(the) best","We have believed","He commanded him"],"correct":1,"explanation":"\"(the) best\", from the word-by-word gloss at 2:197."},{"type":"fill_blank","question":"Type the root of خَيْرُ in Arabic (three letters).","correct":"خير","explanation":"خير. Diacritics are ignored when checking, so خ ي ر is enough."}]', '["root-jnn"]', 15);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes) VALUES ('root-Hsn', 'The root حسن (ح س ن)', 'grammar', 3, '{"explanation":"The root حسن occurs 194 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 30 distinct glossed words, tagged in the corpus as N, V, ADJ, in verb form IV. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"وَحُسْنَ","transliteration":"","meaning":"and good","rule":"3:148"},{"arabic":"حُسْنًۭا","transliteration":"","meaning":"good","rule":"2:83"},{"arabic":"بِأَحْسَنَ","transliteration":"","meaning":"with better","rule":"4:86"},{"arabic":"ٱلْمُحْسِنِينَ","transliteration":"","meaning":"the good-doers (in reward)","rule":"2:58"},{"arabic":"ٱلْحُسْنَيَيْنِ","transliteration":"","meaning":"(of) the two best (things)","rule":"9:52"},{"arabic":"تُحْسِنُوا۟","transliteration":"","meaning":"you do good","rule":"4:128"}],"rules":[{"name":"Words on حسن","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["وَحُسْنَ","حُسْنًۭا","بِأَحْسَنَ","ٱلْمُحْسِنِينَ","ٱلْحُسْنَيَيْنِ","تُحْسِنُوا۟","مُحْسِنٌۭ","حَسَنًا"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root حسن?","options":["لِمُؤْمِنٍۢ","وَحُسْنَ","أَحَدُهُمَآ","تُؤْمِنُوٓا۟"],"correct":1,"explanation":"وَحُسْنَ — glossed \"and good\" at 3:148 — carries the root حسن. The others come from different roots."},{"type":"multiple_choice","question":"What does حُسْنًۭا mean?","options":["(does) Allah","good","(of) humility","(as) nations"],"correct":1,"explanation":"\"good\", from the word-by-word gloss at 2:83."},{"type":"fill_blank","question":"Type the root of بِأَحْسَنَ in Arabic (three letters).","correct":"حسن","explanation":"حسن. Diacritics are ignored when checking, so ح س ن is enough."}]', '["root-xyr"]', 15);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes) VALUES ('root-nwr', 'The root نور (ن و ر)', 'grammar', 3, '{"explanation":"The root نور occurs 194 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 17 distinct glossed words, tagged in the corpus as N, ADJ, in verb form IV. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"ٱلنُّورِ","transliteration":"","meaning":"[the] light","rule":"2:257"},{"arabic":"نُورٌۭ","transliteration":"","meaning":"a light","rule":"5:15"},{"arabic":"ٱلنَّارِ","transliteration":"","meaning":"(of) the Fire","rule":"2:39"},{"arabic":"ٱلنَّارَ","transliteration":"","meaning":"the Fire","rule":"2:24"},{"arabic":"وَنُورٌۭ","transliteration":"","meaning":"and light","rule":"5:44"},{"arabic":"ٱلنُّورَ","transliteration":"","meaning":"the light","rule":"7:157"}],"rules":[{"name":"Words on نور","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["ٱلنُّورِ","نُورٌۭ","ٱلنَّارِ","ٱلنَّارَ","وَنُورٌۭ","ٱلنُّورَ","وَٱلنُّورَ","ٱلنَّارُ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root نور?","options":["ٱلْأُمُورُ","ٱلنُّورِ","وَءَابَآؤُكُم","ٱلذِّكْرِ"],"correct":1,"explanation":"ٱلنُّورِ — glossed \"[the] light\" at 2:257 — carries the root نور. The others come from different roots."},{"type":"multiple_choice","question":"What does نُورٌۭ mean?","options":["Is there any god","a light","and your partners","So Allah protected him"],"correct":1,"explanation":"\"a light\", from the word-by-word gloss at 5:15."},{"type":"fill_blank","question":"Type the root of ٱلنَّارِ in Arabic (three letters).","correct":"نور","explanation":"نور. Diacritics are ignored when checking, so ن و ر is enough."}]', '["root-Hsn