INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes) VALUES ('root-Dll', 'The root ضلل (ض ل ل)', 'grammar', 3, '{"explanation":"The root ضلل occurs 191 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 35 distinct glossed words, tagged in the corpus as N, V, ADJ, in verb forms IV, II. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"تَضِلُّوا۟","transliteration":"","meaning":"you stray","rule":"4:44"},{"arabic":"يَضِلُّ","transliteration":"","meaning":"strays","rule":"6:117"},{"arabic":"ٱلضَّآلِّينَ","transliteration":"","meaning":"(of) those who go astray","rule":"1:7"},{"arabic":"ضَلُّوا۟","transliteration":"","meaning":"they have strayed","rule":"4:167"},{"arabic":"ٱلضَّلَـٰلَةُ","transliteration":"","meaning":"the astraying","rule":"7:30"},{"arabic":"أَضَلَّ","transliteration":"","meaning":"is let astray","rule":"4:88"}],"rules":[{"name":"Words on ضلل","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["تَضِلُّوا۟","يَضِلُّ","ٱلضَّآلِّينَ","ضَلُّوا۟","ٱلضَّلَـٰلَةُ","أَضَلَّ","ٱلضَّلَـٰلَةَ","ضَلَلْتُ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root ضلل?","options":["ٱللَّهُ","يَأْتِىٓ","ٱلشَّيَـٰطِينُ","تَضِلُّوا۟"],"correct":3,"explanation":"تَضِلُّوا۟ — glossed \"you stray\" at 4:44 — carries the root ضلل. The others come from different roots."},{"type":"multiple_choice","question":"What does يَضِلُّ mean?","options":["the remembrance","a sign","strays","let swear"],"correct":2,"explanation":"\"strays\", from the word-by-word gloss at 6:117."},{"type":"fill_blank","question":"Type the root of ٱلضَّآلِّينَ in Arabic (three letters).","correct":"ضلل","explanation":"ضلل. Diacritics are ignored when checking, 