INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes) VALUES ('root-smE', 'The root سمع (س م ع)', 'grammar', 3, '{"explanation":"The root سمع occurs 185 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 28 distinct glossed words, tagged in the corpus as N, V, ADJ, in verb forms IV, VIII, V. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"سَمِيعُ","transliteration":"","meaning":"(are) All-Hearer","rule":"3:38"},{"arabic":"وَٱسْمَعُوا۟","transliteration":"","meaning":"and listen","rule":"2:93"},{"arabic":"سَمِعْتُمْ","transliteration":"","meaning":"you hear","rule":"4:140"},{"arabic":"سَمِيعًۢا","transliteration":"","meaning":"All-Hearing","rule":"4:58"},{"arabic":"وَلَتَسْمَعُنَّ","transliteration":"","meaning":"And you will certainly hear","rule":"3:186"},{"arabic":"أَسْمَعَهُمْ","transliteration":"","meaning":"He had made them hear","rule":"8:23"}],"rules":[{"name":"Words on سمع","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["سَمِيعُ","وَٱسْمَعُوا۟","سَمِعْتُمْ","سَمِيعًۢا","وَلَتَسْمَعُنَّ","أَسْمَعَهُمْ","سَمْعِهِمْ","يَسْمَعُوا۟"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root سمع?","options":["شَدِيدٍۢ","سَمِيعُ","شَرًّۭا","شَآءَ"],"correct":1,"explanation":"سَمِيعُ — glossed \"(are) All-Hearer\" at 3:38 — carries the root سمع. The others come from different roots."},{"type":"multiple_choice","question":"What does وَٱسْمَعُوا۟ mean?","options":["comes to them","Believe","and listen","But Allah saved him"],"correct":2,"explanation":"\"and listen\", from the word-by-word gloss at 2:93."},{"type":"fill_blank","question":"Type the root of سَمِعْتُمْ in Arabic (three letters).","correct":"سمع","explanation":"سمع. Diacritics are ignored when checking, so س م ع is enough."}]', '["root-Dll"]', 15);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes) VALUES ('root-Hyy', 'The root حيي (ح ي ي)', 'grammar', 3, '{"explanation":"The root حيي occurs 184 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 35 distinct glossed words, tagged in the corpus as V, N, ADJ, in verb forms X, IV, II. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"يُحْىِ","transliteration":"","meaning":"revives","rule":"2:73"},{"arabic":"ٱلْحَىُّ","transliteration":"","meaning":"the Ever-Living","rule":"2:255"},{"arabic":"أَحْيَآءٌۭ","transliteration":"","meaning":"(they are) alive","rule":"2:154"},{"arabic":"فَحَيُّوا۟","transliteration":"","meaning":"then greet","rule":"4:86"},{"arabic":"فَأَحْيَيْنَـٰهُ","transliteration":"","meaning":"and We gave him life","rule":"6:122"},{"arabic":"حَيَوٰةٍۢ","transliteration":"","meaning":"life","rule":"2:96"}],"rules":[{"name":"Words on حيي","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["يُحْىِ","ٱلْحَىُّ","أَحْيَآءٌۭ","فَحَيُّوا۟","فَأَحْيَيْنَـٰهُ","حَيَوٰةٍۢ","وَيَحْيَىٰ","يُحْىِۦ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root حيي?","options":["شِقَاقَ","يُحْىِ","ٱلشَّيْطَـٰنُ","أَبَدًا"],"correct":1,"explanation":"يُحْىِ — glossed \"revives\" at 2:73 — carries the root حيي. The others come from different roots."},{"type":"multiple_choice","question":"What does ٱلْحَىُّ mean?","options":["secure","the Ever-Living","To Allah","repeatedly turning"],"correct":1,"explanation":"\"the Ever-Living\", from the word-by-word gloss at 2:255."},{"type":"fill_blank","question":"Type the root of أَحْيَآءٌۭ in Arabic (three letters).","correct":"حيي","explanation":"حيي. Diacritics are ignored when checking, so ح ي ي is enough."}]', '["root-smE"]', 15);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes) VALUES ('root-bny', 'The root بني (ب ن ي)', 'grammar', 3, '{"explanation":"The root بني occurs 184 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 29 distinct glossed words, tagged in the corpus as N, V. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"أَبْنَآءَهُمُ","transliteration":"","meaning":"their sons","rule":"6:20"},{"arabic":"وَأَبْنَآءَكُمْ","transliteration":"","meaning":"and your sons","rule":"3:61"},{"arabic":"بَنِيهِ","transliteration":"","meaning":"(upon) his sons","rule":"2:132"},{"arabic":"يَـٰبَنِىٓ","transliteration":"","meaning":"O Children","rule":"2:40"},{"arabic":"وَأَبْنَآؤُكُمْ","transliteration":"","meaning":"and your children","rule":"4:11"},{"arabic":"وَٱلْبَنِينَ","transliteration":"","meaning":"and [the] sons","rule":"3:14"}],"rules":[{"name":"Words on بني","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["أَبْنَآءَهُمُ","وَأَبْنَآءَكُمْ","بَنِيهِ","يَـٰبَنِىٓ","وَأَبْنَآؤُكُمْ","وَٱلْبَنِينَ","بَنِىٓ","بَنِينَ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root بني?","options":["يُؤْتِيَهُ","أَمَرَهُۥ","أَبْنَآءَهُمُ","أَجْرِىَ"],"correct":2,"explanation":"أَبْنَآءَهُمُ — glossed \"their sons\" at 6:20 — carries the root بني. The others come from different roots."},{"type":"multiple_choice","question":"What does وَأَبْنَآءَكُمْ mean?","options":["as you remember","came to them","(as) a testimony","and your sons"],"correct":3,"explanation":"\"and your sons\", from the word-by-word gloss at 3:61."},{"type":"fill_blank","question":"Type the root of بَنِيهِ in Arabic (three letters).","correct":"بني","explanation":"بني. Diacritics are ignored when checking, so ب ن ي is enough."}]', '["root-Hyy"]', 15);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes) VALUES ('root-xrj', 'The root خرج (خ ر ج)', 'grammar', 3, '{"explanation":"The root خرج occurs 182 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 51 distinct glossed words, tagged in the corpus as V, N, in verb forms IV, X. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"يَخْرُجُ","transliteration":"","meaning":"comes forth","rule":"7:58"},{"arabic":"لَنُخْرِجَنَّكَ","transliteration":"","meaning":"We will surely drive you out","rule":"7:88"},{"arabic":"يُخْرِجُوكَ","transliteration":"","meaning":"drive you out","rule":"8:30"},{"arabic":"خَرَجْتَ","transliteration":"","meaning":"you start forth","rule":"2:149"},{"arabic":"تُخْرَجُونَ","transliteration":"","meaning":"you will be brought forth","rule":"7:25"},{"arabic":"إِخْرَاجٍۢ","transliteration":"","meaning":"driving (them) out","rule":"2:240"}],"rules":[{"name":"Words on خرج","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["يَخْرُجُ","لَنُخْرِجَنَّكَ","يُخْرِجُوكَ","خَرَجْتَ","تُخْرَجُونَ","إِخْرَاجٍۢ","فَأَخْرَجَ","لَخَرَجْنَا"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root خرج?","options":["يَذْكُرُونَ","يُؤْتَ","يَخْرُجُ","أُشْهِدُ"],"correct":2,"explanation":"يَخْرُجُ — glossed \"comes forth\" at 7:58 — carries the root خرج. The others come from different roots."},{"type":"multiple_choice","question":"What does لَنُخْرِجَنَّكَ mean?","options":["(has) Allah","a reminder","I associate","We will surely drive you out"],"correct":3,"explanation":"\"We will surely drive you out\", from the word-by-word gloss at 7:88."},{"type":"fill_blank","question":"Type the root of يُخْرِجُوكَ in Arabic (three letters