INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes) VALUES ('root-SlH', 'The root صلح (ص ل ح)', 'grammar', 3, '{"explanation":"The root صلح occurs 180 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 27 distinct glossed words, tagged in the corpus as N, V, ADJ, PN, in verb form IV. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"مُصْلِحُونَ","transliteration":"","meaning":"(are) reformers","rule":"2:11"},{"arabic":"يَـٰصَـٰلِحُ","transliteration":"","meaning":"O Salih","rule":"7:77"},{"arabic":"وَأَصْلِحْ","transliteration":"","meaning":"and do right","rule":"7:142"},{"arabic":"ٱلْمُصْلِحِ","transliteration":"","meaning":"the amender","rule":"2:220"},{"arabic":"وَأَصْلِحُوا۟","transliteration":"","meaning":"and set right","rule":"8:1"},{"arabic":"ٱلصَّـٰلِحِينَ","transliteration":"","meaning":"the righteous","rule":"2:130"}],"rules":[{"name":"Words on صلح","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["مُصْلِحُونَ","يَـٰصَـٰلِحُ","وَأَصْلِحْ","ٱلْمُصْلِحِ","وَأَصْلِحُوا۟","ٱلصَّـٰلِحِينَ","وَأَصْلَحُوا۟","ٱلْمُصْلِحِينَ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root صلح?","options":["إِفْكٌۭ","أَتَىٰكُمْ","شَدِيدٌۭ","مُصْلِحُونَ"],"correct":3,"explanation":"مُصْلِحُونَ — glossed \"(are) reformers\" at 2:11 — carries the root صلح. The others come from different roots."},{"type":"multiple_choice","question":"What does يَـٰصَـٰلِحُ mean?","options":["O Salih","believes","And you consume","and his brothers"],"correct":0,"explanation":"\"O Salih\", from the word-by-word gloss at 7:77."},{"type":"fill_blank","question":"Type the root of وَأَصْلِحْ in Arabic (three letters).","correct":"صلح","explanation":"صلح. Diacritics are ignored when checking, so ص ل ح is enough."}]', '["root-xrj"]', 15);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes) VALUES ('root-sbl', 'The root سبل (س ب ل)', 'grammar', 3, '{"explanation":"The root سبل occurs 176 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 13 distinct glossed words, tagged in the corpus as N. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"ٱلسَّبِيلَ","transliteration":"","meaning":"(from) the way","rule":"4:44"},{"arabic":"سَبِيلًۢا","transliteration":"","meaning":"(to) a (right) way","rule":"4:137"},{"arabic":"سَبِيلًا","transliteration":"","meaning":"way","rule":"4:22"},{"arabic":"سَبِيلًۭا","transliteration":"","meaning":"(find) a way","rule":"3:97"},{"arabic":"سَبِيلٍ","transliteration":"","meaning":"(through) a way","rule":"4:43"},{"arabic":"ٱلسَّبِيلِ","transliteration":"","meaning":"(of) the way","rule":"2:108"}],"rules":[{"name":"Words on سبل","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["ٱلسَّبِيلَ","سَبِيلًۢا","سَبِيلًا","سَبِيلًۭا","سَبِيلٍ","ٱلسَّبِيلِ","سَبِيلُ","سَبِيلِهِۦ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root سبل?","options":["ءَاثِمٌۭ","وَأَخَذْنَـٰهُم","أَهْلُهَا","ٱلسَّبِيلَ"],"correct":3,"explanation":"ٱلسَّبِيلَ — glossed \"(from) the way\" at 4:44 — carries the root سبل. The others come from different roots."},{"type":"multiple_choice","question":"What does سَبِيلًۢا mean?","options":["(to) a (right) way","Allah has imposed","and (the) captive","(of) the risings"],"correct":0,"explanation":"\"(to) a (right) way\", from the word-by-word gloss at 4:137."},{"type":"fill_blank","question":"Type the root of سَبِيلًا in Arabic (three letters).","correct":"سبل","explanation":"سبل. Diacritics are ignored when checking, so س ب ل is enough."}]', '["root-SlH"]', 15);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes) VALUES ('root-tbE', 'The root تبع (ت ب ع)', 'grammar', 3, '{"explanation":"The root تبع occurs 172 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 40 distinct glossed words, tagged in the corpus as V, N, ADJ, in verb forms VIII, IV, VI. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"تَتَّبِعَ","transliteration":"","meaning":"you follow","rule":"2:120"},{"arabic":"تَبِعَكَ","transliteration":"","meaning":"follows you","rule":"7:18"},{"arabic":"مُتَتَابِعَيْنِ","transliteration":"","meaning":"consecutively","rule":"4:92"},{"arabic":"أَتَّبِعُ","transliteration":"","meaning":"(do) I follow","rule":"6:50"},{"arabic":"تَبِعَ","transliteration":"","meaning":"follows","rule":"2:38"},{"arabic":"ٱتَّبِعُوا۟","transliteration":"","meaning":"Follow","rule":"2:170"}],"rules":[{"name":"Words on تبع","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["تَتَّبِعَ","تَبِعَكَ","مُتَتَابِعَيْنِ","أَتَّبِعُ","تَبِعَ","ٱتَّبِعُوا۟","بِتَابِعٍۢ","ٱتَّبَعَ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root تبع?","options":["ٱللَّهِ","تَتَّبِعَ","أَجْرًۭا","مُشْرِكِينَ"],"correct":1,"explanation":"تَتَّبِعَ — glossed \"you follow\" at 2:120 — carries the root تبع. The others come from different roots."},{"type":"multiple_choice","question":"What does تَبِعَكَ mean?","options":["Is there any god","(have) they taken","follows you","the signs"],"correct":2,"explanation":"\"follows you\", from the word-by-word gloss at 7:18."},{"type":"fill_blank","question":"Type the root of مُتَتَابِعَيْنِ in Arabic (three letters).","correct":"تبع","explanation":"تبع. Diacritics are ignored when checking, so ت ب ع is enough."}]', '["root-sbl"]', 15);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes) VALUES ('root-Awl', 'The root اول (ا و ل)', 'grammar', 3, '{"explanation":"The root اول occurs 170 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 29 distinct glossed words, tagged in the corpus as N, T, ADJ, in verb form II. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"أُو۟لُوا۟","transliteration":"","meaning":"those","rule":"2:269"},{"arabic":"ٱلْأَوَّلِينَ","transliteration":"","meaning":"(of) the former (people)","rule":"6:25"},{"arabic":"وَأُو۟لِى","transliteration":"","meaning":"and those","rule":"4:59"},{"arabic":"أُو۟لِى","transliteration":"","meaning":"those","rule":"4:83"},{"arabic":"ءَالَ","transliteration":"","meaning":"(the) people","rule":"2:50"},{"arabic":"تَأْوِيلِهِۦ","transliteration":"","meaning":"its interpretation","rule":"3:7"}],"rules":[{"name":"Words on اول","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["أُو۟لُوا۟","ٱلْأَوَّلِينَ","وَأُو۟لِى","أُو۟لِى","ءَالَ","تَأْوِيلِهِۦ","ءَالِ","أَوَّلُ"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root اول?","options":["وَيَشْفِ","ٱلْأَمْرُ","أُو۟لُوا۟","يَتَّخِذْ"],"correct":2,"explanation":"أُو۟لُوا۟ — glossed \"those\" at 2:269 — carries the root اول. The others come from different roots."},{"type":"multiple_choice","question":"What does ٱلْأَوَّلِينَ mean?","options":["(of) the former (people)","they will come","the trusts","(to) one of you"],"correct":0,"explanation":"\"(of) the former (people)\", from the word-by-word gloss at 6:25."},{"type":"fill_blank","question":"Type the root of وَأُو۟لِى in Arabic (three letters).","correct":"اول","explanation":"اول. Diacritics are ignored when checking, so ا و ل is enough."}]', '["root-tbE"]', 15);
INSERT OR REPLACE INTO lessons (id, title, module, level, content, exercises, prerequisites, estimated_minutes) VALUES ('root-qtl', 'The root قتل (ق ت ل)', 'grammar', 3, '{"explanation":"The root قتل occurs 170 times in the Quran. Arabic builds words from three-letter roots, so learning one root unlocks every word derived from it — this one appears in 46 distinct glossed words, tagged in the corpus as V, N, in verb forms III, VIII, II. The words below are attested occurrences with their word-by-word glosses.","examples":[{"arabic":"قِتَالٌۭ","transliteration":"","meaning":"Fighting","rule":"2:217"},{"arabic":"يُقَـٰتِلُونَكُمْ","transliteration":"","meaning":"fight you","rule":"2:190"},{"arabic":"۞ فَلْيُقَـٰتِلْ","transliteration":"","meaning":"So let fight","rule":"4:74"},{"arabic":"وَٱقْتُلُوهُمْ","transliteration":"","meaning":"And kill them","rule":"2:191"},{"arabic":"قِتَالٍۢ","transliteration":"","meaning":"(concerning) fighting","rule":"2:217"},{"arabic":"ٱلْقَتْلِ","transliteration":"","meaning":"[the] killing","rule":"2:191"}],"rules":[{"name":"Words on قتل","description":"Attested in the Quranic Arabic Corpus. Each is a real occurrence rather than a constructed example, and the reference is where to find it.","examples":["قِتَالٌۭ","يُقَـٰتِلُونَكُمْ","۞ فَلْيُقَـٰتِلْ","وَٱقْتُلُوهُمْ","قِتَالٍۢ","ٱلْقَتْلِ","فَٱقْتُلُوٓا۟","تُقَـٰتِلُوا۟"]}]}', '[{"type":"multiple_choice","question":"Which of these words is built on the root قتل?","options":["ذَرَأْنَا","بِٱللَّهِ","إِثْمًا","قِتَالٌۭ"],"correct":3,"explanation":"قِتَالٌۭ — glossed \"Fighting\" at 2:217 — carries the root قتل. The others come from different roots."},{"type":"multiple_choice","question":"What does يُقَـٰتِلُونَكُمْ mean?","options":["surely is a sign","fight you","and that may take heed","(the) people"],"correct":1,"explanation":"\"fight you\", from the word-by-word gloss at 2:190."},{"type":"fill_blank","question":"Type the root of ۞ فَلْيُقَـٰتِلْ in Arabic (three letters).","correct":"قتل","explanation":"قتل. Diacritics are ignored when checking, so ق ت ل is enough."}]', '["root-Awl"]', 15);
